// Minimal PDF text extractor: inflate content streams, pull text-showing operators.
// Good enough to locate equations and read surrounding prose in a normal journal PDF.
const fs = require('fs');
const zlib = require('zlib');

const file = process.argv[2];
const buf = fs.readFileSync(file);
const raw = buf.toString('latin1');

const out = [];
let idx = 0;
while (true) {
  const s = raw.indexOf('stream', idx);
  if (s === -1) break;
  let p = s + 6;
  if (raw[p] === '\r') p++;
  if (raw[p] === '\n') p++;
  const e = raw.indexOf('endstream', p);
  if (e === -1) break;
  const slice = buf.slice(p, e);
  idx = e + 9;

  let text = null;
  try {
    text = zlib.inflateSync(slice).toString('latin1');
  } catch {
    try {
      text = zlib.inflateRawSync(slice).toString('latin1');
    } catch {
      continue; // not a flate stream (image, font file, metadata)
    }
  }
  if (!/\bT[jJ]\b|\bTd\b|\bBT\b/.test(text)) continue;

  // Walk the content stream, emitting a newline at each text-positioning operator.
  const parts = [];
  let last = 0;
  const re = /\((?:\\.|[^\\()])*\)\s*Tj|\[(?:[^\][]|\\.)*\]\s*TJ|\bT\*|\bTd\b|\bTD\b|\bET\b/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const chunk = text.slice(last, m.index);
    const tok = m[0];
    if (tok.endsWith('Tj')) {
      const lit = tok.slice(0, tok.lastIndexOf(')'));
      parts.push(decode(lit));
    } else if (tok.endsWith('TJ')) {
      const arr = tok.slice(tok.indexOf('[') + 1, tok.lastIndexOf(']'));
      let s2 = '';
      const re2 = /\((?:\\.|[^\\()])*\)/g;
      let m2;
      while ((m2 = re2.exec(arr)) !== null) s2 += decode(m2[0]);
      parts.push(s2);
    } else {
      parts.push('\n');
    }
    last = m.index + tok.length;
  }
  out.push(parts.join(''));
}

function decode(lit) {
  let s = lit;
  if (s.startsWith('(')) s = s.slice(1);
  if (s.endsWith(')')) s = s.slice(0, -1);
  return s
    .replace(/\\([nrtbf()\\])/g, (_, c) => ({ n: '\n', r: '', t: '\t', b: '', f: '' }[c] ?? c))
    .replace(/\\([0-7]{1,3})/g, (_, o) => String.fromCharCode(parseInt(o, 8)))
    .replace(/\\(.{1,2})/g, '$1');
}

const text = out.join('\n').replace(/\n{3,}/g, '\n\n');
fs.writeFileSync(file.replace(/\.pdf$/i) + '.txt', text, 'latin1');
console.log('extracted chars:', text.length);

