// Airlock: body is alH*0.7 tall, but flanges are placed at +/- alH/2.
// Gap = alH/2 - 0.7*alH/2 = 0.15*alH on each side, unfilled.
const calc = (alR, alH) => {
  const bodyHalf = (alH * 0.7) / 2;
  const flangeY = alH / 2;
  const gap = flangeY - bodyHalf;
  return { alR, alH, bodyHalf, flangeY, gapEachSide: gap, totalGap: gap * 2 };
};
