// Transition length as a function of how far the downcomer is offset in X.
  //
  // The portion of the total that the run and the transition must together supply.
  //
  // NOTE this is `runX + transition`, NOT the full total. An earlier version
  // compared the FULL produced length against this partial target, so
  // lengthExcludingRunAndTransition was counted on both sides. The bisection then
  // saw an objective already far above target at every point, collapsed the
  // bracket to zero, and silently added no run at all ΓÇö which is why the centreline
  // stayed at 18.82 m and the run appeared to do nothing.
  const targetRemaining = totalLengthM - lengthExcludingRunAndTransition;
  let horizontalRunM = 0;

  // ITEM 27, part 2 ΓÇö apply the layout offset, then RE-SOLVE the run against the
  // shifted downcomer position.
  //
  // The bisection above evaluated the objective with the downcomer at riserX + runX.
  // If the layout also carries a plan offset, the downcomer is at
  // riserX + offset + runX, so the objective must be evaluated there. Solving at
  // riserX and shifting afterwards would leave the transition length stale ΓÇö the
  // same class of disagreement this whole block exists to prevent.
  const planOffsetM = layoutPlanOffsetM * bendRadiusM * 2;

  const transitionLengthAt = (runX: number): number =>
    Math.hypot(cycloneInletFlangePoint.x - (riserX + planOffsetM + runX), cycloneInletYM - downcomerExitY);
  const objectiveAt = (runX: number): number => runX + transitionLengthAt(runX);

  horizontalRunM = 0;
  if (objectiveAt(0) < targetRemaining - 0.01) {
    let lo = 0;
    let hi = Math.max(0.1, targetRemaining);
    for (let i = 0; i < 80; i++) {
      const mid = (lo + hi) / 2;
      if (objectiveAt(mid) < targetRemaining) lo = mid;
      else hi = mid;
    }
    horizontalRunM = (lo + hi) / 2;
  }

  const downcomerX = riserX + planOffsetM + horizontalRunM;

