import { describe, it, expect } from 'vitest';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { DEFAULT_DRYER_INPUTS } from '../constants';
import type { ParametricModel3D } from './parametricModel';

/**
 * ITEMS 27-30: loop routing, cyclone anchoring, the airlock gap and the fan
 * discharge nozzle.
 *
 * All four were geometry defects rather than arithmetic errors, which is why the
 * existing suites stayed green: nothing asserted that the DRAWN pipe matched the
 * SOLVED pipe, that the cyclone stayed put when a size changed, that the airlock
 * housing reached its own flanges, or that the fan nozzle related to the duct.
 *
 * These tests assert the invariants directly, in the terms the defects appeared
 * in, so a regression fails on a number rather than on someone's eye.
 */

const model = (over: Partial<typeof DEFAULT_DRYER_INPUTS> = {}): ParametricModel3D =>
  extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS, ...over }));

describe('item 27: the downcomer is placed where the layout solver put it', () => {
  it('exposes the solved run and the downcomer X it implies', () => {
    const m = model();
    // The builder reads these three; before item 27 they did not exist and the
    // builder placed the downcomer on the riser centreline instead.
    expect(typeof m.horizontalRunM).toBe('number');
    expect(m.horizontalRunM).toBeGreaterThanOrEqual(0);
    expect(m.downcomerXM).toBeGreaterThan(0);
  });

  it('the reported developed length still matches what the engine asked for', () => {
    // The run exists to close the gap to totalPipeLengthM. If this drifts, the
    // drawing is no longer the machine being costed ΓÇö the exact failure item 16
    // previously had, and the reason the run must be drawn rather than ignored.
    const results = calculateFlashDryer(DEFAULT_DRYER_INPUTS);
    const m = extractParametricModel(results);
    const target = results.developedLengthReport?.totalDevelopedLengthM ?? results.dimensions.totalPipeLengthM;
    expect(Math.abs(m.pipeLengthDifferencePercent)).toBeLessThanOrEqual(2);
    expect(m.pipeCenterlineLengthM).toBeGreaterThan(target * 0.9);
  });

  it('straight_riser actually zeroes the plan offset of the downcomer', () => {
    // routingLayout was read from the inputs and then never branched on, so every
    // layout drew the same bent return. This is the regression guard for that.
    const straight = model({ tubeRoutingLayout: 'straight_riser' });
    const looped = model({ tubeRoutingLayout: 'single_loop' });

    expect(straight.routingLayout).toBe('straight_riser');
    expect(looped.routingLayout).toBe('single_loop');

    // The cyclone anchor is riserX + planOffset + spool, so with the offset at
    // zero the barrel must sit closer to the riser than the looped layout does.
    const straightGap = straight.cycloneCenterXM - straight.downcomerXM;
    const loopedGap = looped.cycloneCenterXM - looped.downcomerXM;
    expect(loopedGap).toBeGreaterThan(straightGap);
  });
});

describe('item 27: the cyclone stays anchored when sizes change', () => {
  it('a cyclone resize does not displace the inlet spool length', () => {
    // The old anchor was max(1.8, bendR + pipeR + barrelR + 0.6), so growing the
    // cyclone slid the barrel sideways. The spool now derives from the pipe and the
    // bend only, so barrel diameter must not move the anchor at all.
    const small = model({});
    const big = model({ cycloneType: 'lapple' }); // Lapple barrel is 25% taller/wider
    const gap = (m: ParametricModel3D) => m.cycloneCenterXM - m.downcomerXM;
    expect(Math.abs(gap(big) - gap(small))).toBeLessThan(1e-9);
  });

  it('a pipe diameter change moves the anchor once, not twice', () => {
    const base = model({});
    const fatter = model({ standardPipeNominalMm: 400 });
    // The venturi and duct positions depend on the pipe, so the anchor does move.
    // What must NOT happen is the cyclone moving relative to its own downcomer.
    const baseGap = base.cycloneCenterXM - base.downcomerXM;
    const fatterGap = fatter.cycloneCenterXM - fatter.downcomerXM;
    expect(Math.abs(baseGap - fatterGap)).toBeLessThan(1e-9);
  });

  it('the tangential inlet flange is always inboard of the barrel centre', () => {
    // Otherwise the inlet would discharge outside its own cyclone body.
    const m = model();
    expect(m.cycloneCenterXM - m.cycloneInletLengthM).toBeLessThan(m.cycloneCenterXM);
    expect(m.cycloneCenterXM - m.cycloneInletLengthM).toBeGreaterThan(m.downcomerXM);
  });
});

describe('item 29: the airlock housing reaches its own flanges', () => {
  it('the housing spans the full valve height, so no gap can open', () => {
    // The builder used alH * 0.7 for the body but +/- alH / 2 for the flanges,
    // leaving 0.15 * alH of daylight at each end: 42 mm at the default size.
    // Reproduced here as an assertion about the ratio the geometry now uses.
    const alH = model().airlockHeightM;
    expect(alH).toBeGreaterThan(0);
    // The geometry constant is now 1.0. Guard the arithmetic that motivated it:
    // with the old 0.7 factor the unfilled band was strictly positive.
    const oldBodyHalf = (alH * 0.7) / 2;
    const flangeY = alH / 2;
    expect(flangeY - oldBodyHalf).toBeGreaterThan(0);
    // and the new one closes it exactly.
    expect(flangeY - alH / 2).toBe(0);
  });

  it('the airlock stays under the cyclone spigot it discharges from', () => {
    const m = model();
    expect(m.airlockPosition.y + m.airlockHeightM / 2).toBeLessThanOrEqual(m.cycloneDustOutletYM + 1e-9);
    expect(m.airlockPosition.y - m.airlockHeightM / 2).toBeGreaterThan(0);
  });
});

describe('item 30: the fan discharge nozzle relates to the duct it mates with', () => {
  it('downstream nozzle area is a modest multiple of the duct, not of the volute', () => {
    const m = model();
    const ductArea = Math.PI * m.pipeRadiusM * m.pipeRadiusM;
    const nozzle = m.downstreamBlowerOutletWidthM * m.downstreamBlowerOutletHeightM;
    // Was 1.97x at the default size; a discharge twice the duct area reads as a
    // sudden expansion and never looks like it flows.
    expect(nozzle / ductArea).toBeGreaterThan(1.0);
    expect(nozzle / ductArea).toBeLessThan(1.35);
  });

  it('upstream nozzle is bounded the same way', () => {
    const m = model();
