  // depends on the run.
  const l_inlet_elbow_est = (Math.PI / 2) * bendRadiusM;
  const l_inlet_spool_est = inletSpoolLengthM;

  // Everything in the total that is neither the horizontal run nor the fixed inlet
  // transition.
  const lengthExcludingRunAndTransition =
    l_base_elbow_est +
    l_riser_est +
    l_top_ubend_est +
    l_downcomer_est +
    l_venturi_duct_est +
    l_inlet_elbow_est +
    l_inlet_spool_est;

