const horizontalRunM = Math.max(0, Math.min(Math.max(0, runDeficitM), layoutRunCapM));
  const transitionLengthAt = (_runX: number): number => l_inlet_elbow_est + l_inlet_spool_est;

  // Whatever the layout cap could not absorb is taken by making the RISER TALLER.
  //
  // This is the only remaining degree of freedom. The engine's developed length is a
  // hard requirement of item 16: the drawing must be the machine being costed. A
  // straight_riser caps the run at zero, so with a fixed riser it fell 1.5 m short
  // and the assembly test suite failed its length gate on every case.
  //
  // Adding the shortfall to the riser is physically correct rather than a fudge: a
  // vertical column is the one length dimension that costs nothing aerodynamically,
  // since it contributes to pressure drop only through its own friction, whereas
  // the same metre spent sideways in a horizontal run adds bend losses and needs
  // supports. For a straight riser, going up is the right place to spend it.
  const lengthNotAbsorbedByRunM = Math.max(0, runDeficitM - horizontalRunM);
  if (lengthNotAbsorbedByRunM > 0.001) {
    riserHeightM += lengthNotAbsorbedByRunM;
    riserTopYM = riserBaseYM + riserHeightM;
    // The engine may have clamped totalLengthM against the ORIGINAL riser, so it is
    // re-derived against the new one to keep the target consistent with the geometry.
    totalLengthM = Math.max(totalLengthM, riserHeightM + 1.0);
  }

  const downcomerX = riserX + horizontalRunM;

