const flangePt = params.cycloneInletFlangePoint;
  const transitionPts: THREE.Vector3[] = [];

  // Horizontal distance available for the turn, and the rise to climb out of.
  const horizontalReachM = flangePt.x - downcomerX;
  const riseM = params.cycloneInletYM - downcomerExitY;

  if (horizontalReachM > 1e-3 && riseM > 1e-3) {
    // A 90-degree elbow cannot use more than its own radius in each direction, so
    // the radius is capped by the geometry rather than assumed.
    const elbowR = Math.min(params.bendRadiusM, horizontalReachM, riseM);
    const straightRunM = horizontalReachM - elbowR;
    const elbowRiseM = riseM - elbowR;

    // Straight vertical lead-in, so the elbow starts on the vertical tangent.
    transitionPts.push(new THREE.Vector3(downcomerX, downcomerExitY - elbowRiseM, downcomerZ));

    // Quarter-circle elbow from vertical-down to horizontal-+X.
    const elbowSteps = 14;
    for (let i = 1; i <= elbowSteps; i++) {
      const a = (Math.PI / 2) * (i / elbowSteps);
      transitionPts.push(
        new THREE.Vector3(
          downcomerX + elbowR * Math.sin(a),
          downcomerExitY - elbowRiseM - elbowR * Math.cos(a),
          downcomerZ
        )
      );
    }

    // Straight horizontal run into the flange, already on the -X... +X tangent.
    if (straightRunM > 1e-3) {
      transitionPts.push(
        new THREE.Vector3(downcomerX + elbowR + straightRunM * 0.5, params.cycloneInletYM, downcomerZ)
      );
    }
  }

  transitionPts.push(new THREE.Vector3(flangePt.x, params.cycloneInletYM, downcomerZ));

