const flangePt = params.cycloneInletFlangePoint;
  const transitionPts: THREE.Vector3[] = [];

  // Signed geometry of the turn.
  //
  // Both of these can be NEGATIVE, and an earlier version guarded on
  // `horizontalReach > 0 && rise > 0`, which silently skipped the elbow entirely
  // and left a bare diagonal whenever either went negative. On the IITA benchmark
  // the downcomer exits one bend radius ABOVE the inlet centreline (rise = -0.90 m),
  // so the guard was false on every load and no arc was drawn at all ΓÇö the exact
  // "always bent, never smooth" defect it was written to fix.
  //
  // The elbow therefore has to work in BOTH directions: it descends into an inlet
  // below it and rises into one above it. `dirY` carries the sign.
  const horizontalReachM = flangePt.x - downcomerX;
  const riseM = params.cycloneInletYM - downcomerExitY;
  const dirY = Math.sign(riseM) || 1;

  if (Math.abs(horizontalReachM) > 1e-3 && Math.abs(riseM) > 1e-3) {
    // A 90-degree elbow uses one radius in each direction, so the radius is capped
    // by whichever axis is tighter rather than assumed.
    const elbowR = Math.max(
      1e-3,
      Math.min(params.bendRadiusM, Math.abs(horizontalReachM), Math.abs(riseM))
    );
    const straightRunM = Math.abs(horizontalReachM) - elbowR;
    const straightX = downcomerX + Math.sign(horizontalReachM) * elbowR;
