function elbow(downcomerX, exitY, flangeX, inletY, bendR) {
  const reach = flangeX - downcomerX, rise = inletY - exitY;
  const dirY = Math.sign(rise) || 1;
  const pts = [];
  if (Math.abs(reach) > 1e-3 && Math.abs(rise) > 1e-3) {
    const R = Math.max(1e-3, Math.min(bendR, Math.abs(reach), Math.abs(rise)));
    const straightRun = Math.abs(reach) - R;
    const straightX = downcomerX + Math.sign(reach) * R;
    const leadInY = exitY - dirY * (Math.abs(rise) - R);
    pts.push([+downcomerX.toFixed(3), +leadInY.toFixed(3)]);
    const cy = leadInY - dirY * R;
    for (let i = 1; i <= 14; i++) {
      const a = (Math.PI/2)*(i/14);
      pts.push([+(straightX - Math.sign(reach)*R*Math.cos(a)).toFixed(3), +(cy + dirY*R*Math.sin(a)).toFixed(3)]);
    }
    if (straightRun > 1e-3) pts.push([+(straightX + Math.sign(reach)*straightRun/2).toFixed(3), +inletY.toFixed(3)]);
  }
  pts.push([+flangeX.toFixed(3), +inletY.toFixed(3)]);
  return pts;
}
