it('the tangential inlet flange is between the downcomer and the barrel centre', () => {
    // On the default design the flange lands very slightly INBOARD of the downcomer
    // (by 68 mm), because the inlet spool is sized from the pipe and bend while the
    // barrel centre sits a full inlet length further on. So the meaningful invariant
    // is that the flange is within reach of the downcomer and inboard of the barrel ΓÇö
    // not that it is strictly downstream, which is not geometrically required for a
    // tangential entry that may turn back on itself.
    const m = model();
    const flangeX = m.cycloneCenterXM - m.cycloneInletLengthM;
    expect(Math.abs(flangeX - m.downcomerXM)).toBeLessThan(m.cycloneInletLengthM);
    expect(flangeX).toBeLessThan(m.cycloneCenterXM);
  });

