// Verify the suction elbow is tangent-continuous and lands on the nozzle.
const dbX = 7.118, overheadY = 6.751, cyZ = -2.263;
const idZ = -1.937, idY = 0.600, bendR = 0.9;
const yRun = overheadY - idY, zRun = idZ - cyZ;
const arcR = Math.max(1e-3, Math.min(bendR, yRun, Math.abs(zRun)));
const dirZ = Math.sign(zRun);
console.log('yRun', yRun.toFixed(3), 'zRun', zRun.toFixed(3), 'arcR', arcR.toFixed(3));

const pts = [];
pts.push(['drop-end', dbX, idY + arcR, cyZ]);
const centreZ = cyZ + dirZ * arcR;
for (let i = 1; i <= 14; i++) {
  const a = (Math.PI/2)*(i/14);
  pts.push([+(dbX.toFixed(3)), +(idY + arcR - arcR*Math.sin(a)).toFixed(4), +(centreZ - dirZ*arcR*Math.cos(a)).toFixed(4)]);
}
const straightZ = Math.abs(zRun) - arcR;
if (straightZ > 1e-3) pts.push(['straight', dbX, idY, +(cyZ + dirZ*straightZ/2).toFixed(4)]);
pts.push(['NOZZLE', dbX, idY, idZ]);

console.log('\narc first:', pts[1].slice(1));
console.log('arc last :', pts[pts.length-2].slice(1));
console.log('nozzle   :', pts[pts.length-1].slice(1));
console.log('\narc ends on nozzle elevation?', Math.abs(pts[pts.length-2][1] - idY) < 1e-9);
console.log('straight run length', straightZ.toFixed(4), 'm');

// tangents either side of the arc
const d = (p,q)=>[q[1]-p[1],q[2]-p[2],q[3]-p[3]];
const nrm = v => { const L=Math.hypot(...v); return v.map(x=>+(x/L).toFixed(3)); };
console.log('\ntangent entering arc (drop -> arc[0]):', nrm(d(pts[0],pts[1])));
console.log('tangent exiting arc  (arc[-1] -> next):', nrm(d(pts[pts.length-2],pts[pts.length-1])));

