describe('item 33: the exhaust stack is sized from the fan, not the cyclone', () => {
  const ductArea = (m: ParametricModel3D) => Math.PI * m.pipeRadiusM * m.pipeRadiusM;

  it('carries the same discharge area as the nozzle it bolts to', () => {
    // The stack was `max(0.12, cycloneVortexFinderRadiusM * 0.95)` ΓÇö an UPSTREAM
    // component with no dimensional relationship to the fan. On the IITA load that is
    // a 580 mm stack on a 428 mm nozzle. It is now an equal-area round section.
    const m = model();
    const stackArea = Math.PI * m.downstreamStackRadiusM ** 2;
    const nozzle = m.downstreamBlowerOutletWidthM * m.downstreamBlowerOutletHeightM;
    expect(stackArea).toBeCloseTo(nozzle, 3);
  });

  it('no longer follows the vortex finder', () => {
    // The old rule scaled the vent with the cyclone. Doubling the cyclone must not
    // change the fan discharge.
    const small = model({ cycloneType: 'stairmand' });
    const big = model({ cycloneType: 'lapple' });
    expect(Math.abs(big.downstreamStackRadiusM - small.downstreamStackRadiusM)).toBeLessThan(1e-9);
  });

  it('keeps up with the duct as the machine is resized', () => {
    // The stack tracks the duct, so a larger fan passage does not leave the vent
    // stranded at a fixed size.
    const small = model({ standardPipeNominalMm: 100 });
    const big = model({ standardPipeNominalMm: 1000 });
    expect(big.downstreamStackRadiusM).toBeGreaterThan(small.downstreamStackRadiusM);
    expect(big.downstreamStackRadiusM).toBeGreaterThan(ductArea(big) ** 0.5 * 0.5);
  });
});

describe('item 33/34: the exhaust stack clears the suction duct', () => {
  it('no interpenetration on any axis', () => {
    // THE regression guard. On the IITA load the stack and the overhead suction duct
    // overlapped by 0.227 m in X over 2.05 m of Y ΓÇö the vent passing straight through
    // the duct. A number, not an eye.
    const ov = (a: [number, number], b: [number, number]) => Math.min(b[1], a[1]) - Math.max(b[0], a[0]);
    for (const dia of [100, 180, 315, 450, 630, 1000]) {
      for (const lay of ['straight_riser', 'single_loop', 'double_loop'] as const) {
        const m = model({ standardPipeNominalMm: dia, tubeRoutingLayout: lay });
        const sR = m.downstreamStackRadiusM;
        const dR = m.cycloneVortexFinderRadiusM;
        const standoff = m.idSuctionStandoffM;

        const stackX: [number, number] = [m.downstreamBlowerPosition.x - m.downstreamBlowerVoluteRadiusM * 0.5 - sR - m.downstreamBlowerWidthM * 0.5 - sR, m.downstreamBlowerPosition.x - m.downstreamBlowerVoluteRadiusM * 0.5 - m.downstreamBlowerWidthM * 0.5 + sR];
        const ductX: [number, number] = [m.downstreamBlowerPosition.x - dR, m.downstreamBlowerPosition.x + dR];
        const stackY: [number, number] = [m.downstreamBlowerVoluteRadiusM * 0.55, m.downstreamBlowerVoluteRadiusM * 0.55 + 2.4];
        const ductY: [number, number] = [m.downstreamBlowerPosition.y, m.cycloneBarrelTopYM + 1.05];

        expect(ov(stackX, ductX), `D=${dia} ${lay}: stack overlaps duct in X`).toBeLessThan(0);
        expect(standoff, `D=${dia} ${lay}: standoff too small to turn`).toBeGreaterThan(m.bendRadiusM);
      }
    }
  });
});

describe('item 34: the suction elbow has room for a long-radius bend', () => {
  it('the nozzle stands off at least one bend radius', () => {
    // A fixed 0.326 m standoff clamped the elbow to 1.45 pipe diameters ΓÇö a squeeze
    // bend ΓÇö regardless of how large the engine's bend radius was.
    for (const dia of [100, 180, 315, 450, 630, 1000]) {
      const m = model({ standardPipeNominalMm: dia });
      expect(m.idSuctionStandoffM, `D=${dia}`).toBeGreaterThanOrEqual(m.bendRadiusM);
    }
  });

  it('elbow radius is therefore at least 3 pipe diameters on the default design', () => {
    const m = model();
    const elbowR = Math.min(m.bendRadiusM, m.idSuctionStandoffM);
    expect(elbowR / m.pipeRadiusM).toBeGreaterThanOrEqual(3);
  });
});

