    //   (cyX,   overY,  cyZ)             straight up
    //   (cyX+0.35, overY+0.25, cyZ)      <-- moves in X AND Y at once
    //   (dbX-0.35, overY+0.25, cyZ)      straight across
    //   (dbX,   overY,  cyZ)             <-- moves in X AND Y at once
    //
    // Two separate 90 degree corners, each faked by a single diagonal step. A
    // Catmull-Rom spline needs direction either side of a turn to round it, and a
    // diagonal step supplies none, so the spline overshot both corners. That is the
    // kink across the top of the arch ΓÇö and this IS the "180 degree curve" the user
    // reported, being two quarter bends plus a straight.
    //
    // It is now two explicit quarter arcs of the engine's bend radius with a straight
    // between them: up the vortex finder, arc over to horizontal, straight across,
    // arc down to the drop. Tangent continuity is by construction, and the arcs
    // consume exactly the rise and the run they need.
    const overheadPts: THREE.Vector3[] = [];

    // Radius for the two crown bends. Each consumes one radius of X, so the pair must
    // fit the available span or the arch cannot be drawn as two proper bends.
    const crownSpanM = Math.abs(dbPos.x - cyX);
    const crownR = Math.max(1e-3, Math.min(params.bendRadiusM, crownSpanM / 2));
    const crownRiseM = Math.max(1e-3, overheadY - cyTopY);
    const crownRiser = Math.min(crownR, crownRiseM);

    // Straight up out of the vortex finder.
    overheadPts.push(new THREE.Vector3(cyX, cyTopY, cyZ));
    overheadPts.push(new THREE.Vector3(cyX, overheadY - crownRiser, cyZ));

    // Crown bend 1: vertical (+Y) to horizontal (+X). Centre one radius along +X.
    {
      const steps = 14;
      const cx = cyX + crownRiser;
      const cy = overheadY - crownRiser;
      for (let i = 1; i <= steps; i++) {
        const a = (Math.PI / 2) * (i / steps);
        overheadPts.push(
          new THREE.Vector3(cx - crownRiser * Math.cos(a), cy + crownRiser * Math.sin(a), cyZ)
        );
      }
    }

    // Straight across at the crown.
    const crownStraightM = crownSpanM - 2 * crownR;
    if (crownStraightM > 1e-3) {
      overheadPts.push(
        new THREE.Vector3(
          cyX + crownR + crownStraightM / 2,
          overheadY,
          cyZ
        )
      );
    }

    // Crown bend 2: horizontal (+X) to vertical (-Y). Mirror of the first.
    {
      const steps = 14;
      const cx = dbPos.x - crownRiser;
      const cy = overheadY - crownRiser;
      for (let i = 1; i <= steps; i++) {
        const a = (Math.PI / 2) * (i / steps);
        overheadPts.push(
          new THREE.Vector3(cx + crownRiser * Math.sin(a), cy + crownRiser * Math.cos(a), cyZ)
        );
      }
    }

