// ONE radius for both crown bends. Two different radii cannot share a single crown
    // elevation: bend 1 must END where bend 2 BEGINS, and each puts its centre one
    // radius along its entry axis, so a mismatched pair leaves a gap at the apex.
    const crownSpanM = Math.abs(dbPos.x - cyX);
    const crownRiseM = overheadY - cyTopY;
    // The radius is limited by the SPAN (two bends must fit across it) and by the
    // RISE (a bend cannot be taller than the vertical it starts on). An earlier
    // version clamped these separately and then used the rise figure for the X
    // geometry, which put bend 1's end at X = cyX + 0.65 while bend 2 started at
    // X = dbX - 0.90 ΓÇö they crossed over each other.
    const crownR = Math.max(1e-3, Math.min(params.bendRadiusM, crownSpanM / 2, crownRiseM));

    // The apex sits one radius above the entry elevation, because that is where a
    // quarter bend from vertical reaches horizontal. overheadY is therefore derived
    // from the geometry rather than assumed, so the arch always closes.
    const crownApexYM = cyTopY + crownR;

