// Crown bend 2: horizontal (+X) to vertical (-Y).
    //
    // Centre at (dbX - R, cyTopY), radius R, running from a = 0 at the crown to
    // a = 90 deg on the drop axis:
    //
    //     x = (dbX - R) + R sin a      dx/da = R cos a   ->  +X at entry, -Y... no, 0 at exit
    //     y = cyTopY       + R cos a      dy/da = -R sin a
    //
    // so the tangent is (cos a, -sin a): pure +X where it joins the crown straight and
    // pure -Y where it leaves for the drop. Writing the y term as `apex - R sin a`
    // instead ΓÇö which looks equivalent ΓÇö tilts the tangent diagonally at BOTH ends
    // and reintroduces the kink, because apex = cyTopY + R only coincides with the
    // centre form at a = 0.
    {
      const steps = 16;
      for (let i = 1; i <= steps; i++) {
        const a = (Math.PI / 2) * (i / steps);
        overheadPts.push(
          new THREE.Vector3(
            dbPos.x - crownR + crownR * Math.sin(a),
            params.cycloneBarrelTopYM + 0.4 - crownR + crownR * Math.cos(a),
            cyZ
          )
        );
      }
    }

