import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);

/** World-space AABB of a mesh, after applying the full parent transform chain. */
function worldBox(obj: THREE.Object3D): THREE.Box3 {
  obj.updateWorldMatrix(true, true);
  const box = new THREE.Box3();
  box.setFromObject(obj, true);
  return box;
}

describe('probe: drawn cyclone inlet connection', () => {
  it('measures the drawn scene', () => {
    const params = extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }));
    const materials: Record<string, THREE.Material> = new Proxy(
      {} as Record<string, THREE.Material>,
      {
        get: (t, k: string) => {
          if (!t[k]) t[k] = new THREE.MeshStandardMaterial();
          return t[k];
        },
        has: () => true,
      }
    ) as never;

    const { rootGroup } = buildMechanicalCadAssembly(params, materials);

    // --- locate the pieces -------------------------------------------------
    const pipes: THREE.Mesh[] = [];
    const cyc: THREE.Object3D[] = [];
    rootGroup.traverse((o) => {
      if (!(o as THREE.Mesh).isMesh) return;
      let n: THREE.Object3D | null = o;
      while (n) {
        if (n.name === 'flash_pipe_system') { pipes.push(o as THREE.Mesh); break; }
        if (n.name === 'cyclone_separator') { cyc.push(o as THREE.Object3D); break; }
        n = n.parent;
      }
    });

    const tubeBoxes = pipes
      .map((m) => ({ m, b: worldBox(m) }))
      .filter(({ b }) => Math.abs(f(b.min.y) - f(params.downcomerExitYM)) < 0.6);

    const cycBoxes = cyc.map((m) => ({ m, b: worldBox(m) }));

    // The transition tube is the pipe mesh whose max.x reaches the inlet flange.
    const flangeX = params.cycloneInletFlangePoint.x;
    const transition = tubeBoxes
      .filter(({ b }) => b.max.x > flangeX - 1e-6 && b.max.x < flangeX + 0.35)
      .sort((a, b) => a.b.max.x - b.b.max.x)[0];

    const report = {
      flangePoint: {
        x: f(params.cycloneInletFlangePoint.x),
        y: f(params.cycloneInletFlangePoint.y),
        z: f(params.cycloneInletFlangePoint.z),
      },
      transitionTube: transition
        ? {
            min: { x: f(transition.b.min.x), y: f(transition.b.min.y), z: f(transition.b.min.z) },
            max: { x: f(transition.b.max.x), y: f(transition.b.max.y), z: f(transition.b.max.z) },
            gapX_to_flange: f(flangeX - transition.b.max.x),
            midY: f((transition.b.min.y + transition.b.max.y) / 2),
          }
        : null,
      cycloneMeshes: cycBoxes
        .map(({ m, b }) => ({
          geo: (m as THREE.Mesh).geometry.type,
          min: { x: f(b.min.x), y: f(b.min.y), z: f(b.min.z) },
          max: { x: f(b.max.x), y: f(b.max.y), z: f(b.max.z) },
        }))
        .filter((r) => Math.abs(r.max.x - f(flangeX)) < 0.05 || Math.abs(r.min.x - f(flangeX)) < 0.05),
    };

    writeFileSync(`${process.env.TEMP}\\probe2.json`, JSON.stringify(report, null, 2));
  });
});

