import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { DEFAULT_DRYER_INPUTS } from '../constants';

describe('probe: was the 3.2 floor ever reachable?', () => {
  it('sweeps inletYM + bendRadiusM', () => {
    const rows: Record<string, number>[] = [];
    let min = Infinity;
    let argmin = '';
    for (const dia of [80, 100, 150, 180, 250, 315, 450, 630, 1000]) {
      for (const kg of [200, 500, 1000, 2000, 4000, 8000, 20000, 60000]) {
        const m = extractParametricModel(
          calculateFlashDryer({
            ...DEFAULT_DRYER_INPUTS,
            standardPipeNominalMm: dia,
            feedRateKgH: kg,
          } as never)
        );
        const sum = m.cycloneInletYM + m.bendRadiusM;
        rows.push({ dia, kg, inletYM: +m.cycloneInletYM.toFixed(3), bendR: +m.bendRadiusM.toFixed(3), sum: +sum.toFixed(3) });
        if (sum < min) { min = sum; argmin = `D=${dia} kg=${kg}`; }
      }
    }
    writeFileSync(
      `${process.env.TEMP}\\probe3.json`,
      JSON.stringify({ minSum: +min.toFixed(3), argmin, rows }, null, 1)
    );
  });
});

