import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);
const v3 = (v: THREE.Vector3) => ({ x: f(v.x), y: f(v.y), z: f(v.z) });

function centreline(mesh: THREE.Mesh): THREE.Vector3[] {
  const geo = mesh.geometry as THREE.TubeGeometry;
  const pos = geo.attributes.position;
  const perRing = geo.parameters.radialSegments + 1;
  const distinct = perRing - 1;
  const out: THREE.Vector3[] = [];
  for (let r = 0; r < pos.count / perRing; r++) {
    const v = new THREE.Vector3();
    for (let i = 0; i < distinct; i++) {
      v.x += pos.getX(r * perRing + i);
      v.y += pos.getY(r * perRing + i);
      v.z += pos.getZ(r * perRing + i);
    }
    out.push(v.divideScalar(distinct));
  }
  return out;
}

describe('probe: full cyclone inlet chain', () => {
  it('dumps every drawn piece around the inlet', () => {
    const m = extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }));
    const { rootGroup } = buildMechanicalCadAssembly(m, createCadMaterials());

    const groups = new Map<string, THREE.Mesh[]>();
    rootGroup.traverse((o) => {
      if (!(o as THREE.Mesh).isMesh) return;
      let n: THREE.Object3D | null = o;
      while (n) {
        if (n.name.startsWith('component_')) {
          const list = groups.get(n.name) ?? [];
          list.push(o as THREE.Mesh);
          groups.set(n.name, list);
          break;
        }
        n = n.parent;
      }
    });

    const report: Record<string, unknown> = {
      model: {
        pipeDiameterMm: f(m.standardPipeNominalMm ?? 0),
        pipeRadiusM: f(m.pipeRadiusM),
        pipeOuterDiameter: f(m.pipeRadiusM * 2),
        cycloneBarrelRadiusM: f(m.cycloneBarrelRadiusM),
        cycloneInletWidthM: f(m.cycloneInletWidthM),
        cycloneInletHeightM: f(m.cycloneInletHeightM),
        cycloneInletLengthM: f(m.cycloneInletLengthM),
        cycloneCenterXM: f(m.cycloneCenterXM),
        cycloneCenterZM: f(m.cycloneCenterZM),
        cycloneBarrelTopYM: f(m.cycloneBarrelTopYM),
        cycloneJunctionYM: f(m.cycloneJunctionYM),
        downcomerXM: f(m.downcomerXM),
        downcomerExitYM: f(m.downcomerExitYM),
        flangePoint: m.cycloneInletFlangePoint,
      },
      FIT: {
        // Does the round duct even fit through the rectangular slot it must enter?
        ductFitsSlotWidth: m.pipeRadiusM * 2 <= m.cycloneInletWidthM,
        ductDiameter: f(m.pipeRadiusM * 2),
        slotWidth: f(m.cycloneInletWidthM),
        overhangEachSide: f((m.pipeRadiusM * 2 - m.cycloneInletWidthM) / 2),
        ductFitsSlotHeight: m.pipeRadiusM * 2 <= m.cycloneInletHeightM,
        slotHeight: f(m.cycloneInletHeightM),
      },
      cycloneMeshes: (groups.get('component_cyclone') ?? []).map((mesh) => {
        const b = new THREE.Box3().setFromObject(mesh, true);
        return {
          geo: mesh.geometry.type,
          localPos: v3(mesh.position),
          min: v3(b.min),
          max: v3(b.max),
        };
      }),
      pipeTubes: (groups.get('component_column') ?? [])
        .filter((x) => (x.geometry as THREE.TubeGeometry).parameters)
        .map((x) => {
          const cl = centreline(x);
          return { start: v3(cl[0]), end: v3(cl.at(-1)!) };
        }),
    };

    writeFileSync(`${process.env.TEMP}\\probe4.json`, JSON.stringify(report, null, 1));
  });
});

