import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { deflateSync } from 'node:zlib';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

// ---------------------------------------------------------------------------
// Minimal software renderer: z-buffered triangle rasteriser + PNG encoder.
// Lets the built scene actually be LOOKED AT, which none of the numeric checks
// have managed to do.
// ---------------------------------------------------------------------------

const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf: Buffer): number {
  let c = -1;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

function chunk(type: string, data: Buffer): Buffer {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}

function encodePng(w: number, h: number, rgb: Uint8Array): Buffer {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: truecolour
  const raw = Buffer.alloc(h * (w * 3 + 1));
  for (let y = 0; y < h; y++) {
    raw[y * (w * 3 + 1)] = 0;
    Buffer.from(rgb.buffer, y * w * 3, w * 3).copy(raw, y * (w * 3 + 1) + 1);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 6 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

interface Tri {
  v: [THREE.Vector3, THREE.Vector3, THREE.Vector3];
  col: [number, number, number];
}

function collect(root: THREE.Object3D, wanted: string[], colour: [number, number, number], out: Tri[]) {
  root.updateWorldMatrix(true, true);
  root.traverse((o) => {
    if (!(o as THREE.Mesh).isMesh) return;
    let n: THREE.Object3D | null = o;
    let hit = false;
    while (n) {
      if (wanted.includes(n.name)) { hit = true; break; }
      n = n.parent;
    }
    if (!hit) return;
    const g = (o as THREE.Mesh).geometry;
    const pos = g.attributes.position;
    const idx = g.index;
    const m = (o as THREE.Object3D).matrixWorld;
    const count = idx ? idx.count : pos.count;
    const a = new THREE.Vector3();
    const b = new THREE.Vector3();
    const c = new THREE.Vector3();
    for (let i = 0; i < count; i += 3) {
      const i0 = idx ? idx.getX(i) : i;
      const i1 = idx ? idx.getX(i + 1) : i + 1;
      const i2 = idx ? idx.getX(i + 2) : i + 2;
      if (i1 >= pos.count || i2 >= pos.count) continue;
      a.fromBufferAttribute(pos, i0).applyMatrix4(m);
      b.fromBufferAttribute(pos, i1).applyMatrix4(m);
      c.fromBufferAttribute(pos, i2).applyMatrix4(m);
      out.push({ v: [a, b, c], col: colour });
    }
  });
}

function render(tris: Tri[], w: number, h: number, camPos: THREE.Vector3, target: THREE.Vector3, fovDeg: number): Uint8Array {
  const rgb = new Uint8Array(w * h * 3);
  const zbuf = new Float64Array(w * h).fill(Infinity);
  // Background: dark grid-ish gradient like the app's dark viewport.
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = (y * w + x) * 3;
      const g = 12 + Math.floor(10 * (1 - y / h));
      rgb[i] = 6; rgb[i + 1] = g; rgb[i + 2] = 14;
    }
  }

  const cam = new THREE.PerspectiveCamera(fovDeg, w / h, 0.05, 200);
  cam.position.copy(camPos);
  cam.lookAt(target);
  cam.updateMatrixWorld(true);
  cam.updateProjectionMatrix();
  const vp = new THREE.Matrix4().multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);

  const light = new THREE.Vector3(12, 18, 14).normalize();
  const screen = tris.map((t) => {
    const p = t.v.map((v) => {
      const e = v.clone().applyMatrix4(vp);
      return { x: (e.x + 1) / 2 * w, y: (1 - e.y) / 2 * h, z: e.z };
    });
    return { p, col: t.col };
  });

  screen.sort((a, b) => {
    const da = (a.p[0].z + a.p[1].z + a.p[2].z) / 3;
    const db = (b.p[0].z + b.p[1].z + b.p[2].z) / 3;
    return db - da; // far (large z in NDC is nearer for perspective... three uses -1..1, smaller = further)
  });

  for (const { p, col } of screen) {
    const [A, B, C] = p;
    const minX = Math.max(0, Math.floor(Math.min(A.x, B.x, C.x)));
    const maxX = Math.min(w - 1, Math.ceil(Math.max(A.x, B.x, C.x)));
