function render(tris: Tri[], w: number, h: number, camPos: THREE.Vector3, target: THREE.Vector3, fovDeg: number): Uint8Array {
  const rgb = new Uint8Array(w * h * 3);
  const zbuf = new Float64Array(w * h).fill(Infinity);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = (y * w + x) * 3;
      rgb[i] = 8; rgb[i + 1] = 12; rgb[i + 2] = 18;
    }
  }

  const cam = new THREE.PerspectiveCamera(fovDeg, w / h, 0.05, 200);
  cam.position.copy(camPos);
  cam.lookAt(target);
  cam.updateMatrixWorld(true);
  cam.updateProjectionMatrix();
  const vp = new THREE.Matrix4().multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);

  const key = new THREE.Vector3(12, 18, 14).normalize();
  const fill = new THREE.Vector3(-12, 8, -8).normalize();

  for (const t of tris) {
    const [A3, B3, C3] = t.v;
    // World-space face normal for shading (skip degenerate).
    const e1 = new THREE.Vector3().subVectors(B3, A3);
    const e2 = new THREE.Vector3().subVectors(C3, A3);
    const nrm = new THREE.Vector3().crossVectors(e1, e2);
    if (nrm.lengthSq() < 1e-14) continue;
    nrm.normalize();
    const facing = nrm.dot(camPos.clone().sub(A3)) > 0 ? 1 : -1;
    nrm.multiplyScalar(facing);
    const lam = 0.22 + 0.62 * Math.max(0, nrm.dot(key)) + 0.22 * Math.max(0, nrm.dot(fill));
    const sh = Math.min(1.35, lam);

    const e = t.v.map((v) => v.clone().applyMatrix4(vp));
    const [A, B, C] = e;
    const minX = Math.max(0, Math.floor(Math.min(A.x, B.x, C.x)));
    const maxX = Math.min(w - 1, Math.ceil(Math.max(A.x, B.x, C.x)));
    const minY = Math.max(0, Math.floor(Math.min(A.y, B.y, C.y)));
    const maxY = Math.min(h - 1, Math.ceil(Math.max(A.y, B.y, C.y)));
    if (minX > maxX || minY > maxY) continue;

    const cross = (ux: number, uy: number, vx: number, vy: number) => ux * vy - uy * vx;
    const den = cross(B.x - A.x, B.y - A.y, C.x - A.x, C.y - A.y);
    if (Math.abs(den) < 1e-9) continue;

    for (let y = minY; y <= maxY; y++) {
      for (let x = minX; x <= maxX; x++) {
        const px = x + 0.5;
        const py = y + 0.5;
        const lB = cross(px - A.x, py - A.y, C.x - A.x, C.y - A.y) / den;
        const lC = cross(B.x - A.x, B.y - A.y, px - A.x, py - A.y) / den;
        const lA = 1 - lB - lC;
        if (lA < 0 || lB < 0 || lC < 0) continue;
        const z = lA * A.z + lB * B.z + lC * C.z;
        const k = y * w + x;
        if (z >= zbuf[k]) continue;
        zbuf[k] = z;
        const o = k * 3;
        rgb[o] = Math.min(255, colOf(t)[0] * sh);
        rgb[o + 1] = Math.min(255, colOf(t)[1] * sh);
        rgb[o + 2] = Math.min(255, colOf(t)[2] * sh);
      }
    }
  }
  return rgb;
}

const colOf = (t: Tri): [number, number, number] => t.col;

