const key = new THREE.Vector3(12, 18, 14).normalize();
  const fill = new THREE.Vector3(-12, 8, -8).normalize();

  // Painter's algorithm only, sorted back to front. A z-buffer needs 1/z
  // interpolation (z is not linear in screen space); interpolating z directly lets
  // large triangles self-occlude and silently drop most of the scene.
  type Item = {
    A: { x: number; y: number; d: number };
    B: { x: number; y: number; d: number };
    C: { x: number; y: number; d: number };
    col: [number, number, number];
    sh: number;
  };
  const items: Item[] = [];

  for (const t of tris) {
    const [A3, B3, C3] = t.v;
    const e1 = new THREE.Vector3().subVectors(B3, A3);
    const e2 = new THREE.Vector3().subVectors(C3, A3);
    const nrm = new THREE.Vector3().crossVectors(e1, e2);
    if (nrm.lengthSq() < 1e-14) continue;
    nrm.normalize();
    if (nrm.dot(camPos.clone().sub(A3)) < 0) nrm.negate(); // two-sided lighting
    const lam = 0.22 + 0.62 * Math.max(0, nrm.dot(key)) + 0.22 * Math.max(0, nrm.dot(fill));

    const proj = t.v.map((v) => v.clone().applyMatrix4(vp));
    if (proj.some((p) => !Number.isFinite(p.x) || p.z < -1 || p.z > 1)) continue;
    const [A, B, C] = proj;
    if (A.z <= 0 || B.z <= 0 || C.z <= 0) continue;
    items.push({
      A: { x: ((A.x + 1) / 2) * w, y: ((1 - A.y) / 2) * h, d: A.z },
      B: { x: ((B.x + 1) / 2) * w, y: ((1 - B.y) / 2) * h, d: B.z },
      C: { x: ((C.x + 1) / 2) * w, y: ((1 - C.y) / 2) * h, d: C.z },
      col: t.col,
      sh: Math.min(1.3, lam),
    });
  }

  items.sort((p, q) => (q.A.d + q.B.d + q.C.d) - (p.A.d + p.B.d + p.C.d));

  for (const it of items) {
    const { A, B, C } = it;
    const minX = Math.max(0, Math.floor(Math.min(A.x, B.x, C.x)));
    const maxX = Math.min(w - 1, Math.ceil(Math.max(A.x, B.x, C.x)));
    const minY = Math.max(0, Math.floor(Math.min(A.y, B.y, C.y)));
