import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { deflateSync } from 'node:zlib';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

// Minimal software renderer so the built scene can actually be LOOKED AT.
// Painter's algorithm only: z is not linear in screen space, so a z-buffer fed
// linearly interpolated z lets large triangles self-occlude and silently drops
// most of the scene.

const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf: Buffer): number {
  let c = -1;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

function chunk(type: string, data: Buffer): Buffer {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}

function encodePng(w: number, h: number, rgb: Uint8Array): Buffer {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8;
  ihdr[9] = 2;
  const raw = Buffer.alloc(h * (w * 3 + 1));
  for (let y = 0; y < h; y++) {
    raw[y * (w * 3 + 1)] = 0;
    Buffer.from(rgb.buffer, y * w * 3, w * 3).copy(raw, y * (w * 3 + 1) + 1);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 6 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

interface Tri {
  v: [THREE.Vector3, THREE.Vector3, THREE.Vector3];
  col: [number, number, number];
}

function collect(root: THREE.Object3D, wanted: string[], colour: [number, number, number], out: Tri[]) {
  root.updateWorldMatrix(true, true);
  root.traverse((o) => {
    if (!(o as THREE.Mesh).isMesh) return;
    let n: THREE.Object3D | null = o;
    let hit = false;
    while (n) {
      if (wanted.includes(n.name)) { hit = true; break; }
      n = n.parent;
    }
    if (!hit) return;
    const mesh = o as THREE.Mesh;
    const g = mesh.geometry;
    const pos = g.attributes.position;
    const idx = g.index;
    const m = mesh.matrixWorld;
    const count = idx ? idx.count : pos.count;
    const a = new THREE.Vector3();
    const b = new THREE.Vector3();
    const c = new THREE.Vector3();
    for (let i = 0; i + 2 < count; i += 3) {
      const i0 = idx ? idx.getX(i) : i;
      const i1 = idx ? idx.getX(i + 1) : i + 1;
      const i2 = idx ? idx.getX(i + 2) : i + 2;
      if (i1 >= pos.count || i2 >= pos.count) continue;
      a.fromBufferAttribute(pos, i0).applyMatrix4(m);
      b.fromBufferAttribute(pos, i1).applyMatrix4(m);
      c.fromBufferAttribute(pos, i2).applyMatrix4(m);
      out.push({ v: [a.clone(), b.clone(), c.clone()], col: colour });
    }
  });
}

interface Item {
  ax: number; ay: number; bx: number; by: number; cx: number; cy: number;
  depth: number;
  col: [number, number, number];
  sh: number;
}

function render(
  tris: Tri[],
  w: number,
  h: number,
  camPos: THREE.Vector3,
  target: THREE.Vector3,
  fovDeg: number
): Uint8Array {
  const rgb = new Uint8Array(w * h * 3);
  for (let i = 0; i < w * h; i++) { rgb[i * 3] = 10; rgb[i * 3 + 1] = 14; rgb[i * 3 + 2] = 22; }

  const cam = new THREE.PerspectiveCamera(fovDeg, w / h, 0.05, 500);
  cam.position.copy(camPos);
  cam.up.set(0, 1, 0);
  cam.lookAt(target);
  cam.updateMatrixWorld(true);
  cam.updateProjectionMatrix();
  const vp = new THREE.Matrix4().multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);

  const key = new THREE.Vector3(12, 18, 14).normalize();
  const fill = new THREE.Vector3(-12, 8, -8).normalize();
  const items: Item[] = [];

  for (const t of tris) {
    const [A3, B3, C3] = t.v;
    const nrm = new THREE.Vector3()
      .crossVectors(new THREE.Vector3().subVectors(B3, A3), new THREE.Vector3().subVectors(C3, A3));
    if (nrm.lengthSq() < 1e-14) continue;
    nrm.normalize();
    const toCam = camPos.clone().sub(A3);
    if (nrm.dot(toCam) < 0) nrm.negate(); // two-sided
    const lam = 0.25 + 0.6 * Math.max(0, nrm.dot(key)) + 0.2 * Math.max(0, nrm.dot(fill));

    const pr = t.v.map((v) => v.clone().applyMatrix4(vp));
    if (pr.some((p) => !Number.isFinite(p.x) || !Number.isFinite(p.y))) continue;
    const [A, B, C] = pr;
    if (A.z <= -1 || B.z <= -1 || C.z <= -1) continue; // behind or at the near plane
    const depth = (A.z + B.z + C.z) / 3;
    items.push({
      ax: ((A.x + 1) / 2) * w, ay: ((1 - A.y) / 2) * h,
      bx: ((B.x + 1) / 2) * w, by: ((1 - B.y) / 2) * h,
      cx: ((C.x + 1) / 2) * w, cy: ((1 - C.y) / 2) * h,
      depth,
      col: t.col,
      sh: Math.min(1.25, lam),
    });
  }

  // Far to near. Larger NDC z is further away.
  items.sort((p, q) => q.depth - p.depth);

  for (const it of items) {
    const { ax, ay, bx, by, cx, cy, col, sh } = it;
    const minX = Math.max(0, Math.floor(Math.min(ax, bx, cx)));
    const maxX = Math.min(w - 1, Math.ceil(Math.max(ax, bx, cx)));
    const minY = Math.max(0, Math.floor(Math.min(ay, by, cy)));
    const maxY = Math.min(h - 1, Math.ceil(Math.max(ay, by, cy)));
    if (minX > maxX || minY > maxY) continue;
    const den = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    if (Math.abs(den) < 1e-9) continue;
    const r = Math.round(Math.min(255, col[0] * sh));
    const g = Math.round(Math.min(255, col[1] * sh));
    const bl = Math.round(Math.min(255, col[2] * sh));
    for (let y = minY; y <= maxY; y++) {
      for (let x = minX; x <= maxX; x++) {
        const px = x + 0.5;
        const py = y + 0.5;
        const lB = ((px - ax) * (cy - ay) - (py - ay) * (cx - ax)) / den;
        const lC = ((bx - ax) * (py - ay) - (by - ay) * (px - ax)) / den;
        const lA = 1 - lB - lC;
        if (lA < -1e-9 || lB < -1e-9 || lC < -1e-9) continue;
        const o = (y * w + x) * 3;
        rgb[o] = r; rgb[o + 1] = g; rgb[o + 2] = bl;
      }
    }
  }
  return rgb;
}

describe('render the cyclone inlet', () => {
  it('writes PNGs', () => {
    const model = extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }));
    const { rootGroup, bounds } = buildMechanicalCadAssembly(model, createCadMaterials());

    const pipe: Tri[] = [];
    const cyc: Tri[] = [];
    const str: Tri[] = [];
    collect(rootGroup, ['component_column'], [60, 225, 175], pipe);
    collect(rootGroup, ['component_cyclone'], [240, 238, 248], cyc);
    collect(rootGroup, ['component_structure'], [45, 95, 72], str);

    const out = `${process.env.TEMP}`;
    const centre = bounds.getCenter(new THREE.Vector3());
    const size = bounds.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z, 6.0);
    const dist = (maxDim / 2) / Math.tan(((40 * Math.PI) / 180) / 2) * 1.3;
    const iso = new THREE.Vector3(1.0, 0.72, 1.15).normalize();

    writeFileSync(`${out}\\render_wide.png`, encodePng(760, 760, render([...str, ...cyc, ...pipe], 760, 760, centre.clone().add(iso.clone().multiplyScalar(dist)), centre, 40)));

    const inlet = new THREE.Vector3(model.cycloneInletFlangePoint.x, model.cycloneInletYM, model.cycloneInletFlangePoint.z);
    writeFileSync(`${out}\\render_close.png`, encodePng(760, 760, render([...cyc, ...pipe], 760, 760, inlet.clone().add(iso.clone().multiplyScalar(2.6)), inlet, 40)));
    writeFileSync(`${out}\\render_cyc.png`, encodePng(760, 760, render(cyc, 760, 760, inlet.clone().add(iso.clone().multiplyScalar(2.6)), inlet, 40)));

    writeFileSync(`${out}\\render_diag.json`, JSON.stringify({ pipe: pipe.length, cyc: cyc.length, str: str.length, centre, size, maxDim, dist }, null, 1));
  });
});

