const cycloneInletLengthM = cycloneBarrelRadiusM * 1.5;

  // ITEM 37 ΓÇö the transition between the flash duct and the cyclone's tangential inlet.
  //
  // These two are sized independently and they do not match:
  //
  //   duct      round, D = standard pipe size          450 mm on the IITA load
  //   inlet     rectangular, b x a = 0.2 Dc x 0.5 Dc   231 x 579 mm
  //
  // The inlet proportions are the Stairmand/Lapple convention and are correct for the
  // cyclone, so they stay. The duct is a user-chosen standard size. So a transition is
  // genuinely required, and it has to be a REAL one: the section has to land exactly on
  // the inlet rectangle, or the gas path is blocked.
  //
  // Length is set by the larger of the two half-dimension changes, at a 1:2.5 wall
  // angle (~22 deg, the usual limit for a spun or flued sheet-metal transition). Using
  // only the half-WIDTH change would put a 1:1.7 wall on the converging side at small
  // inlet widths, which is not buildable.
  const inletHalfH = cycloneInletHeightM / 2;
  const inletHalfW = cycloneInletWidthM / 2;
  const ductRadiusM = tubeDiameterStandardM / 2 + pipeWallThicknessM / 2;
  const cycloneInletTransitionLengthM = Math.max(
    0.12,
    2.5 * Math.max(Math.abs(ductRadiusM - inletHalfH), Math.abs(ductRadiusM - inletHalfW))
  );
  // The tangential stub left over once the transition has taken its length. This is what
  // actually enters the barrel, so it must be non-negative.
  const cycloneInletStubLengthM = Math.max(0.05, cycloneInletLengthM - cycloneInletTransitionLengthM);

