// Length is set by the larger of the two half-dimension changes, at a 1:2.5 wall
  // angle (~22 deg, the usual limit for a spun or flued sheet-metal transition). Using
  // only the half-WIDTH change would put a 1:1.7 wall on the converging side at narrow
  // inlet widths, which is not buildable.
  //
  // It is then capped so the assembly cannot run past the barrel centre. The cap only
  // binds when the two sections are so far apart that no transition can absorb it ΓÇö
  // a 1000 mm duct needs b >= 1000 mm, hence Dc >= 5000 mm, against the ~1200 mm the
  // flow actually calls for. No transition fixes that; the cyclone is simply undersized
  // for the selected pipe. Capping keeps the model from drawing a nozzle straight
  // through the far wall of the barrel, which is the least-bad way to represent a
  // combination that has no solution. At the IITA load the cap is not close to binding.
  const inletHalfH = cycloneInletHeightM / 2;
  const inletHalfW = cycloneInletWidthM / 2;
  const ductRadiusM = pipeRadiusM; // outer radius of the flash duct arriving here
  const inletWallAngleLimitM =
    2.5 * Math.max(Math.abs(ductRadiusM - inletHalfH), Math.abs(ductRadiusM - inletHalfW));
  // 0.92 leaves 8% of the flange-to-centre run for the stub.
  const inletRunCapM = 0.92 * cycloneInletLengthM;
  const cycloneInletTransitionLengthM = Math.max(
    0.12,
    Math.min(inletWallAngleLimitM, inletRunCapM)
  );
  // The tangential stub. It must not reach the barrel centre: a tangential nozzle that
  // spans the whole diameter is far deeper than any real one. Penetration is measured
  // from the shell.
  const inletPenetrationM = Math.min(0.15, cycloneBarrelRadiusM / 2);
  const stubOuterLocalM = -cycloneInletLengthM + cycloneInletTransitionLengthM;
  const stubInnerTargetLocalM = -cycloneBarrelRadiusM + inletPenetrationM;
  const cycloneInletStubLengthM = Math.max(
    0,
    Math.min(stubInnerTargetLocalM - stubOuterLocalM, -stubOuterLocalM)
  );

