      expect(model.cycloneInletStubLengthM, `D=${dia}: stub shorter than the minimum`).toBeGreaterThanOrEqual(0.08 - 1e-12);
    }
  });

  it('the transition length keeps the walls inside a buildable angle', () => {
    // 1:2.5, ~22 deg ΓÇö the usual limit for a sheet-metal transition. Derived from the
