    // on the old graphite background a near-black fog blended the far end of the machine
    // into the backdrop. With a white background and a black fog the same geometry fades
    // to BLACK, which reads as a hole in the drawing rather than as distance.
    scene.fog = new THREE.FogExp2(0xffffff, 0.016);

