    const c = document.querySelector('canvas');
    const W = 62, H = 44;
    const g = document.createElement('canvas');
    g.width = W; g.height = H;
    const ctx = g.getContext('2d');
    ctx.fillStyle = '#fff'; ctx.fillRect(0,0,W,H);
    ctx.drawImage(c, 0, 0, W, H);
    const d = ctx.getImageData(0,0,W,H).data;
    const ramp = ' .:-=+*#%@';
    let rows = [];
    let tones = new Set();
    for (let y = 0; y < H; y++) {
      let line = '';
      for (let x = 0; x < W; x++) {
        const i = (y*W+x)*4;
        const lum = 0.2126*d[i] + 0.7152*d[i+1] + 0.0722*d[i+2];
        tones.add(Math.round(lum/16)*16);
        line += ramp[Math.min(9, Math.max(0, Math.floor((255-lum)/25.6)))];
      }
      rows.push(line);
    }
    return { map: rows.join('\\n'), tones: [...tones].sort((a,b)=>a-b) };
  })()`
});
const v = out.value || {};
