import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);

function cl(mesh: THREE.Mesh): THREE.Vector3[] {
  const g = mesh.geometry as THREE.TubeGeometry;
  const pos = g.attributes.position;
  const per = g.parameters.radialSegments + 1;
  const out: THREE.Vector3[] = [];
  for (let r = 0; r < pos.count / per; r++) {
    const v = new THREE.Vector3();
    for (let i = 0; i < per - 1; i++) {
      v.x += pos.getX(r * per + i); v.y += pos.getY(r * per + i); v.z += pos.getZ(r * per + i);
    }
    out.push(v.divideScalar(per - 1));
  }
  return out;
}

describe('probe: cyclone outlet arch + fan suction', () => {
  it('dumps', () => {
    const m = extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }));
    const { rootGroup } = buildMechanicalCadAssembly(m, createCadMaterials());
    const meshes: THREE.Mesh[] = [];
    rootGroup.traverse((o) => {
      if (!(o as THREE.Mesh).isMesh) return;
      let n: THREE.Object3D | null = o;
      while (n) { if (n.name === 'overhead_id_suction_duct') { meshes.push(o as THREE.Mesh); break; } n = n.parent; }
    });
    const tube = meshes.find((x) => x.geometry.type === 'TubeGeometry');
    const line = cl(tube!);
    const vfTopY = m.cycloneBarrelTopYM + 0.4;
    const dbX = m.downstreamBlowerPosition.x;
    const cyX = m.cycloneCenterXM;
    const crownSpan = Math.abs(dbX - cyX);
    const R = Math.max(1e-3, Math.min(m.bendRadiusM, crownSpan / 2, vfTopY * 0 + 0.65));

    // Sample the drawn centreline across the crown: is the apex flat or round?
    const apexY = Math.max(...line.map((p) => p.y));
    const atApex = line.filter((p) => p.y > apexY - 0.02).map((p) => p.x);
    const straightAtTop = atApex.length > 1 ? Math.max(...atApex) - Math.min(...atApex) : 0;

    writeFileSync(`${process.env.TEMP}\\arch.json`, JSON.stringify({
      vfTopY: f(vfTopY), cycloneCenterXM: f(cyX), fanX: f(dbX),
      crownSpan: f(crownSpan), bendRadiusM: f(m.bendRadiusM),
      radiusNeededForTrue180: f(crownSpan / 2),
      radiusActuallyUsed: f(R),
      flatTopLength: f(straightAtTop),
      apexY: f(apexY), apexAboveVf: f(apexY - vfTopY),
      idSuctionStandoffM: f(m.idSuctionStandoffM),
      fanNozzle: m.downstreamBlowerInletRadiusM,
      drawnFirst: line[0] && { x: f(line[0].x), y: f(line[0].y), z: f(line[0].z) },
      drawnLast: line.at(-1) && { x: f(line.at(-1)!.x), y: f(line.at(-1)!.y), z: f(line.at(-1)!.z) },
      centrelinePoints: line.length,
    }, null, 1));
  });
});

