import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);

describe('probe: fan suction nozzle vs duct end', () => {
  it('dumps', () => {
    const m = extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }));
    const { rootGroup } = buildMechanicalCadAssembly(m, createCadMaterials());

    // Every mesh inside the blower group, world AABB.
    const blower: { name: string; geo: string; min: number[]; max: number[] }[] = [];
    rootGroup.traverse((o) => {
      if (!(o as THREE.Mesh).isMesh) return;
      let n: THREE.Object3D | null = o;
      while (n) {
        if (n.name === 'component_blower') {
          const b = new THREE.Box3().setFromObject(o as THREE.Mesh, true);
          blower.push({
            name: (o as THREE.Mesh).name || '(unnamed)',
            geo: (o as THREE.Mesh).geometry.type,
            min: [f(b.min.x), f(b.min.y), f(b.min.z)],
            max: [f(b.max.x), f(b.max.y), f(b.max.z)],
          });
          break;
        }
        n = n.parent;
      }
    });

    // The suction nozzle is the cylinder whose Z extent is above the volute centre.
    const dbPos = m.downstreamBlowerPosition;
    const nozzles = blower.filter(
      (x) => x.geo === 'CylinderGeometry' && x.min[2] > dbPos.z + 0.05 && x.max[1] > dbPos.y - 1e-6 && x.max[1] < dbPos.y + 2
    );

    writeFileSync(`${process.env.TEMP}\\noz.json`, JSON.stringify({
      dbPos: { x: f(dbPos.x), y: f(dbPos.y), z: f(dbPos.z) },
      blowerWidthM: f(m.downstreamBlowerWidthM),
      voluteRadiusM: f(m.downstreamBlowerVoluteRadiusM),
      inletRadiusM: f(m.downstreamBlowerInletRadiusM),
      idSuctionStandoffM: f(m.idSuctionStandoffM),
      drawnSuctionNozzles: nozzles,
      nozzleOuterFaceZ: nozzles.length ? f(nozzles[0].max[2]) : null,
      ductEndsAtZ: f(dbPos.z + m.idSuctionStandoffM),
      gapToNozzleFace: nozzles.length ? f(nozzles[0].max[2] - (dbPos.z + m.idSuctionStandoffM)) : null,
      ductRadius: f(m.cycloneVortexFinderRadiusM),
      bendRadiusM: f(m.bendRadiusM),
      crownSpanM: f(Math.abs(dbPos.x - m.cycloneCenterXM)),
      crownSpanHalf: f(Math.abs(dbPos.x - m.cycloneCenterXM) / 2),
      crownSpanHalfExceedsBendRadius: Math.abs(dbPos.x - m.cycloneCenterXM) / 2 > m.bendRadiusM,
      ductDiameter: f(m.cycloneVortexFinderRadiusM * 2),
      nozzleThroatDiameter: f(m.downstreamBlowerInletRadiusM * 2),
    }, null, 1));
  });
});

