import { extractParametricModel } from './parametricModel';
import { DEFAULT_DRYER_INPUTS } from '../constants';

describe('probe: can R = crownSpan/2 always be respected?', () => {
  it('sweeps', () => {
    const rows: unknown[] = [];
    let worst = Infinity;
    let worstAt = '';
    for (const dia of [80, 100, 180, 250, 315, 450, 630, 1000, 1600]) {
      for (const kg of [100, 200, 500, 1000, 2000, 4000, 8000, 20000, 60000]) {
        const m = extractParametricModel(
          calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS, standardPipeNominalMm: dia, feedRateKgH: kg } as never)
        );
        const span = Math.abs(m.downstreamBlowerPosition.x - m.cycloneCenterXM);
        const need = span / 2;
        const slack = need - m.bendRadiusM;
        rows.push({ dia, kg, span: +span.toFixed(3), needR: +need.toFixed(3), bendR: +m.bendRadiusM.toFixed(3), slack: +slack.toFixed(3) });
        if (slack < worst) { worst = slack; worstAt = `D=${dia} kg=${kg}`; }
      }
    }
    const bad = rows.filter((r) => (r as { slack: number }).slack < 0);
    writeFileSync(`${process.env.TEMP}\\sweep.json}`, JSON.stringify({ worstSlack: +worst.toFixed(4), worstAt, violating: bad }, null, 1)
      .replace("}$}", "}"));
  });
});

