import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);

function cl(mesh: THREE.Mesh): THREE.Vector3[] {
  const g = mesh.geometry as THREE.TubeGeometry;
  const pos = g.attributes.position;
  const per = g.parameters.radialSegments + 1;
  const out: THREE.Vector3[] = [];
  for (let r = 0; r < pos.count / per; r++) {
    const v = new THREE.Vector3();
    for (let i = 0; i < per - 1; i++) {
      v.x += pos.getX(r * per + i); v.y += pos.getY(r * per + i); v.z += pos.getZ(r * per + i);
    }
    out.push(v.divideScalar(per - 1));
  }
  return out;
}

describe('verify item 38', () => {
  it('measures the drawn arch and joint', () => {
    const m = extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }));
    const { rootGroup } = buildMechanicalCadAssembly(m, createCadMaterials());

    const ductMeshes: THREE.Mesh[] = [];
    const blowerMeshes: THREE.Mesh[] = [];
    rootGroup.traverse((o) => {
      if (!(o as THREE.Mesh).isMesh) return;
      let n: THREE.Object3D | null = o;
      while (n) {
        if (n.name === 'overhead_id_suction_duct') { ductMeshes.push(o as THREE.Mesh); break; }
        if (n.name === 'component_blower') { blowerMeshes.push(o as THREE.Mesh); break; }
        n = n.parent;
      }
    });
    const tube = ductMeshes.find((x) => x.geometry.type === 'TubeGeometry')!;
    const line = cl(tube);

    const cyTopY = m.cycloneBarrelTopYM + 0.4;
    const cyX = m.cycloneCenterXM;
    const dbX = m.downstreamBlowerPosition.x;
    const R = Math.abs(dbX - cyX) / 2;
    const centre = new THREE.Vector3(cyX + R, cyTopY, m.cycloneCenterZM);

    // (1) flat at the apex
    const apexY = Math.max(...line.map((p) => p.y));
    const near = line.filter((p) => p.y > apexY - 0.02).map((p) => p.x);
    const flat = near.length > 1 ? Math.max(...near) - Math.min(...near) : 0;

    // (2) radius of the arch rings (those above the entry elevation)
    const arch = line.filter((p) => p.y > cyTopY + 1e-3);
    const radii = arch.map((p) => p.distanceTo(centre));
    const rMin = Math.min(...radii), rMax = Math.max(...radii);

    // (6) endpoints
    const first = line[0], last = line.at(-1)!;
    // nozzle face, drawn
    const noz = blowerMeshes
      .filter((x) => x.geometry.type === 'CylinderGeometry')
      .map((x) => new THREE.Box3().setFromObject(x, true))
      .filter((b) => b.min.z > m.downstreamBlowerPosition.z + 0.05 && b.max.z < m.downstreamBlowerPosition.z + 3)
      .sort((a, b) => b.max.z - a.max.z)[0];
    const reducer = ductMeshes.filter((x) => x.geometry.type === 'CylinderGeometry' && x.geometry.type === 'CylinderGeometry');
    const redBox = reducer.length ? new THREE.Box3().setFromObject(reducer[0], true) : null;

    writeFileSync(`${process.env.TEMP}\\verify.json`, JSON.stringify({
      crownSpan: f(R * 2), radiusUsed: f(R), bendRadiusM: f(m.bendRadiusM),
      radiusAtLeastBendRadius: R >= m.bendRadiusM - 1e-6,
      apexY: f(apexY), apexAboveVf: f(apexY - cyTopY), expectedApexAboveVf: f(R),
      flatAtApex: f(flat),
      archRingCount: arch.length,
      archRadiusMin: f(rMin), archRadiusMax: f(rMax),
      archRadiusErrorMm: f((rMax - rMin) * 1000),
      first: { x: f(first.x), y: f(first.y), z: f(first.z) },
      expectedFirst: { x: f(cyX), y: f(cyTopY), z: f(m.cycloneCenterZM) },
      last: { x: f(last.x), y: f(last.y), z: f(last.z) },
      tubeEndGapToNozzleFace: noz ? f(noz.max.z - last.z) : null,
      nozzleFaceZ: noz ? f(noz.max.z) : null,
      reducerLen: f(m.idSuctionReducerLengthM),
      reducerBox: redBox ? { min: [f(redBox.min.x), f(redBox.min.y), f(redBox.min.z)], max: [f(redBox.max.x), f(redBox.max.y), f(redBox.max.z)] } : null,
      ductDiameter: f(m.cycloneVortexFinderRadiusM * 2),
      throatDiameter: f(m.downstreamBlowerInletRadiusM * 2),
    }, null, 1));
  });
});

