import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);

function centreline(mesh: THREE.Mesh): THREE.Vector3[] {
  const g = mesh.geometry as THREE.TubeGeometry;
  const pos = g.attributes.position;
  const per = g.parameters.radialSegments + 1;
  const out: THREE.Vector3[] = [];
  for (let r = 0; r < pos.count / per; r++) {
    const v = new THREE.Vector3();
    for (let i = 0; i < per - 1; i++) {
      v.x += pos.getX(r * per + i); v.y += pos.getY(r * per + i); v.z += pos.getZ(r * per + i);
    }
    out.push(v.divideScalar(per - 1));
  }
  return out;
}

/** Sweep the INLET interface: duct end vs reducer far ring vs stub outer face vs shell. */
describe('probe: cyclone inlet at scale', () => {
  it('sweeps', () => {
    const rows: Record<string, number | string | boolean>[] = [];
    for (const dia of [315, 450, 630, 800, 1000, 1250, 1600]) {
      for (const kg of [1000, 4000, 10000, 25000, 50000, 100000]) {
        const m = extractParametricModel(
          calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS, standardPipeNominalMm: dia, feedRateKgH: kg } as never)
        );
        const { rootGroup } = buildMechanicalCadAssembly(m, createCadMaterials());
        const pipe: THREE.Mesh[] = [];
        const cyc: THREE.Object3D[] = [];
        rootGroup.traverse((o) => {
          if (!(o as THREE.Mesh).isMesh) return;
          let n: THREE.Object3D | null = o;
          while (n) {
            if (n.name === 'component_column') { pipe.push(o as THREE.Mesh); break; }
            if (n.name === 'component_cyclone') { cyc.push(o as THREE.Object3D); break; }
            n = n.parent;
          }
        });
        const flangeX = m.cycloneInletFlangePoint.x;
        const tube = pipe
          .filter((x) => (x.geometry as THREE.TubeGeometry).parameters)
          .map((x) => ({ x, end: centreline(x).at(-1)! }))
          .filter(({ end }) => end.x > flangeX - 1e-6 && end.x < flangeX + 0.4)
          .sort((a, b) => a.end.x - b.end.x)[0].x;
        const line = centreline(tube);
        const ductEnd = line.at(-1)!;

        // the loft = the only raw BufferGeometry in the pipe group
        const loft = pipe.find((x) => x.geometry.type === 'BufferGeometry');
        const pos = (loft!.geometry as THREE.BufferGeometry).attributes.position;
        const half = pos.count / 2;
        const far = new THREE.Vector3();
        let farMinY = Infinity, farMaxY = -Infinity, farMinZ = Infinity, farMaxZ = -Infinity;
        for (let i = half; i < pos.count; i++) {
          const y = pos.getY(i), z = pos.getZ(i);
          farMinY = Math.min(farMinY, y); farMaxY = Math.max(farMaxY, y);
          farMinZ = Math.min(farMinZ, z); farMaxZ = Math.max(farMaxZ, z);
        }
        far.set(pos.getX(half), (farMinY + farMaxY) / 2, (farMinZ + farMaxZ) / 2);

        // cyclone stub = BoxGeometry whose X starts near the transition end
        const transEnd = m.cycloneInletFlangePoint.x + m.cycloneInletTransitionLengthM;
        const shellX = m.cycloneCenterXM - m.cycloneBarrelRadiusM;
        let stubOuter: number | null = null;
        for (const c of cyc) {
          const mesh = c as THREE.Mesh;
          if (!mesh.isMesh || mesh.geometry.type !== 'BoxGeometry') continue;
          const b = new THREE.Box3().setFromObject(mesh, true);
          if (Math.abs(b.min.x - transEnd) < 0.05) stubOuter = b.min.x;
        }

        rows.push({
          dia, kg,
          ductD: f(m.pipeRadiusM * 2),
          inletSlot: `${f(m.cycloneInletWidthM)}x${f(m.cycloneInletHeightM)}`,
          barrelR: f(m.cycloneBarrelRadiusM),
          transLen: f(m.cycloneInletTransitionLengthM),
          stubLen: f(m.cycloneInletStubLengthM),
          ductEndX: f(ductEnd.x), transEndX: f(transEnd),
          gapDuctToTrans: f(transEnd - ductEnd.x),
          stubOuterX: stubOuter === null ? null : f(stubOuter),
          shellX: f(shellX),
          transEndVsShell: f(transEnd - shellX),
          // does the transition end still reach the barrel?
          reachesBarrel: transEnd > shellX,
          // is the stub positive?
          stubPositive: m.cycloneInletStubLengthM > 0,
          // is the transition running past the barrel centre?
          crossesCentre: transEnd > m.cycloneCenterXM,
        });
      }
    }
    const bad = rows.filter((r) => !r.reachesBarrel || !r.stubPositive || r.crossesCentre);
    writeFileSync(`${process.env.TEMP}\\inlet.json`, JSON.stringify({ total: rows.length, badCount: bad.length, bad, rows }, null, 1));
  });
});

