            if (n.name === 'component_column') { pipe.push(o as THREE.Mesh); break; }
            if (n.name === 'component_cyclone') { cyc.push(o as THREE.Mesh); break; }
            n = n.parent;
          }
        });

        const flangeX = m.cycloneInletFlangePoint.x;
        const tube = pipe
          .filter((x) => (x.geometry as THREE.TubeGeometry).parameters)
          .map((x) => ({ x, end: centreline(x).at(-1)! }))
          .filter(({ end }) => end.x > flangeX - 1e-6 && end.x < flangeX + 0.4)
          .sort((a, b) => a.end.x - b.end.x)[0].x;
        const ductEnd = centreline(tube).at(-1)!;

        const loft = pipe.find((x) => x.geometry.type === 'BufferGeometry')!;
        const pos = (loft.geometry as THREE.BufferGeometry).attributes.position;
        const half = pos.count / 2;
        let farMinY = Infinity, farMaxY = -Infinity, farMinZ = Infinity, farMaxZ = -Infinity;
        for (let i = half; i < pos.count; i++) {
          const y = pos.getY(i), z = pos.getZ(i);
          farMinY = Math.min(farMinY, y); farMaxY = Math.max(farMaxY, y);
          farMinZ = Math.min(farMinZ, z); farMaxZ = Math.max(farMaxZ, z);
        }
        const transEndX = pos.getX(half);

        // The stub is the cyclone BoxGeometry whose Y size is the inlet height and whose
        // Z size is the inlet width. Identify by SHAPE, not position.
        let stub: THREE.Box3 | null = null;
        for (const c of cyc) {
          if (c.geometry.type !== 'BoxGeometry') continue;
          const b = new THREE.Box3().setFromObject(c, true);
          const sy = b.max.y - b.min.y, sz = b.max.z - b.min.z;
          if (Math.abs(sy - m.cycloneInletHeightM) < 1e-6 && Math.abs(sz - m.cycloneInletWidthM) < 1e-6) stub = b;
        }
        const shellX = m.cycloneCenterXM - m.cycloneBarrelRadiusM;
        const stubOuterX = stub ? stub.min.x : null;
        const inletInnerX = stub ? stub.max.x : null;

        // What the joint checker reports for this joint
        const rep = validateAssemblyConnections(m);
        const joint = rep.joints.find((j) => j.upstreamPort === 'flashTube.outlet' && j.downstreamPort === 'cyclone.inlet');

        // Does the gas path actually reach inside the barrel?
        const reachesInside = (inletInnerX ?? transEndX) > shellX;

        rows.push({
          dia, kg,
          ductD: f(m.pipeRadiusM * 2),
          slot: `${f(m.cycloneInletWidthM)}x${f(m.cycloneInletHeightM)}`,
          barrelR: f(m.cycloneBarrelRadiusM),
          transLen: f(m.cycloneInletTransitionLengthM),
          stubLen: f(m.cycloneInletStubLengthM),
          ductEndX: f(ductEnd.x),
          transEndX: f(transEndX),
          gapDuctToTransition: f(transEndX - ductEnd.x),
          stubOuterX: stubOuterX === null ? null : f(stubOuterX),
          gapTransitionToStub: stubOuterX === null ? null : f(stubOuterX - transEndX),
          inletInnerX: inletInnerX === null ? null : f(inletInnerX),
          shellX: f(shellX),
          reachesInside,
          checkerSays: joint?.status,
          checkerGapMm: joint?.gapMm,
          checkerAngle: joint?.angularMisalignmentDeg,
        });
      }
    }
    const bad = rows.filter((r) => !r.reachesInside || Math.abs((r.gapTransitionToStub as number) ?? 0) > 1e-6);
    writeFileSync(`${process.env.TEMP}\\inlet2.json`, JSON.stringify({ total: rows.length, badCount: bad.length, bad, rows }, null, 1));
  });
});

