import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel, validateAssemblyConnections } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);

function centreline(mesh: THREE.Mesh): THREE.Vector3[] {
  const g = mesh.geometry as THREE.TubeGeometry;
  const pos = g.attributes.position;
  const per = g.parameters.radialSegments + 1;
  const out: THREE.Vector3[] = [];
  for (let r = 0; r < pos.count / per; r++) {
    const v = new THREE.Vector3();
    for (let i = 0; i < per - 1; i++) {
      v.x += pos.getX(r * per + i); v.y += pos.getY(r * per + i); v.z += pos.getZ(r * per + i);
    }
    out.push(v.divideScalar(per - 1));
  }
  return out;
}

describe('probe: inlet vs capacity', () => {
  it('sweeps', () => {
    const rows: Record<string, unknown>[] = [];
    for (const dia of [315, 450, 630, 800, 1000, 1250, 1600]) {
      for (const kgh of [500, 2000, 5000, 15000, 40000, 90000]) {
        const res = calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS, standardPipeNominalMm: dia, wetFeedRateKgH: kgh } as never);
        const m = extractParametricModel(res);
        const { rootGroup } = buildMechanicalCadAssembly(m, createCadMaterials());
        const pipe: THREE.Mesh[] = [];
        const cyc: THREE.Mesh[] = [];
        rootGroup.traverse((o) => {
          if (!(o as THREE.Mesh).isMesh) return;
          let n: THREE.Object3D | null = o;
          while (n) {
            if (n.name === 'component_column') { pipe.push(o as THREE.Mesh); break; }
            if (n.name === 'component_cyclone') { cyc.push(o as THREE.Mesh); break; }
            n = n.parent;
          }
        });
        const flangeX = m.cycloneInletFlangePoint.x;
        const tube = pipe
          .filter((x) => (x.geometry as THREE.TubeGeometry).parameters)
          .map((x) => ({ x, end: centreline(x).at(-1)! }))
          .filter(({ end }) => end.x > flangeX - 1e-6 && end.x < flangeX + 0.4)
          .sort((a, b) => a.end.x - b.end.x)[0].x;
        const ductEnd = centreline(tube).at(-1)!;

        const loft = pipe.find((x) => x.geometry.type === 'BufferGeometry');
        let transEndX: number | null = null;
        let farHalfH = 0, farHalfW = 0;
        if (loft) {
          const pos = (loft.geometry as THREE.BufferGeometry).attributes.position;
          const half = pos.count / 2;
          let mny = Infinity, mxy = -Infinity, mnz = Infinity, mxz = -Infinity;
          for (let i = half; i < pos.count; i++) {
            const y = pos.getY(i), z = pos.getZ(i);
            mny = Math.min(mny, y); mxy = Math.max(mxy, y);
            mnz = Math.min(mnz, z); mxz = Math.max(mxz, z);
          }
          transEndX = pos.getX(half);
          farHalfH = f((mxy - mny) / 2);
          farHalfW = f((mxz - mnz) / 2);
        }
        let stub: THREE.Box3 | null = null;
        for (const c of cyc) {
          if (c.geometry.type !== 'BoxGeometry') continue;
          const b = new THREE.Box3().setFromObject(c, true);
          if (Math.abs((b.max.y - b.min.y) - m.cycloneInletHeightM) < 1e-6 &&
              Math.abs((b.max.z - b.min.z) - m.cycloneInletWidthM) < 1e-6) stub = b;
        }
        const shellX = m.cycloneCenterXM - m.cycloneBarrelRadiusM;
        const rep = validateAssemblyConnections(m);
        const joint = rep.joints.find((j) => j.upstreamPort === 'flashTube.outlet' && j.downstreamPort === 'cyclone.inlet');

        rows.push({
          dia, kgh,
          ductD: f(m.pipeRadiusM * 2),
          slotW: f(m.cycloneInletWidthM),
          slotH: f(m.cycloneInletHeightM),
          barrelR: f(m.cycloneBarrelRadiusM),
          transLen: f(m.cycloneInletTransitionLengthM),
          stubLen: f(m.cycloneInletStubLengthM),
          ductEndX: f(ductEnd.x),
          transEndX,
          stubOuterX: stub ? f(stub.min.x) : null,
          stubInnerX: stub ? f(stub.max.x) : null,
          farHalfH, farHalfW,
          wantHalfH: f(m.cycloneInletHeightM / 2),
          wantHalfW: f(m.cycloneInletWidthM / 2),
          shellX: f(shellX),
          reachesInside: (stub ? stub.max.x : (transEndX as number)) > shellX,
          checker: joint?.status,
          checkerGap: joint?.gapMm,
        });
      }
    }
    const bad = rows.filter(
      (r) => !r.reachesInside ||
        Math.abs((r.farHalfH as number) - (r.wantHalfH as number)) > 1e-3 ||
        Math.abs((r.farHalfW as number) - (r.wantHalfW as number)) > 1e-3
    );
    writeFileSync(`${process.env.TEMP}\\inlet3.json`, JSON.stringify({ total: rows.length, badCount: bad.length, rows }, null, 1));
  });
});

