import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { deflateSync } from 'node:zlib';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c; }
  return t;
})();
function crc32(b: Buffer) { let c = -1; for (let i = 0; i < b.length; i++) c = CRC_TABLE[(c ^ b[i]) & 0xff] ^ (c >>> 8); return (c ^ -1) >>> 0; }
function chunk(t: string, d: Buffer) {
  const l = Buffer.alloc(4); l.writeUInt32BE(d.length);
  const body = Buffer.concat([Buffer.from(t, 'ascii'), d]);
  const c = Buffer.alloc(4); c.writeUInt32BE(crc32(body));
  return Buffer.concat([l, body, c]);
}
function png(w: number, h: number, rgb: Uint8Array) {
  const ih = Buffer.alloc(13); ih.writeUInt32BE(w, 0); ih.writeUInt32BE(h, 4); ih[8] = 8; ih[9] = 2;
  const raw = Buffer.alloc(h * (w * 3 + 1));
  for (let y = 0; y < h; y++) { raw[y * (w * 3 + 1)] = 0; Buffer.from(rgb.buffer, y * w * 3, w * 3).copy(raw, y * (w * 3 + 1) + 1); }
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', ih), chunk('IDAT', deflateSync(raw, { level: 6 })), chunk('IEND', Buffer.alloc(0))]);
}

interface Tri { v: [THREE.Vector3, THREE.Vector3, THREE.Vector3]; col: [number, number, number] }

function collect(root: THREE.Object3D, wanted: string[], col: [number, number, number], out: Tri[]) {
  root.updateWorldMatrix(true, true);
  root.traverse((o) => {
    if (!(o as THREE.Mesh).isMesh) return;
    let n: THREE.Object3D | null = o; let hit = false;
    while (n) { if (wanted.includes(n.name)) { hit = true; break; } n = n.parent; }
    if (!hit) return;
    const mesh = o as THREE.Mesh; const g = mesh.geometry; const pos = g.attributes.position; const idx = g.index;
    const cnt = idx ? idx.count : pos.count; const m = mesh.matrixWorld;
    const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3();
    for (let i = 0; i + 2 < cnt; i += 3) {
      const i0 = idx ? idx.getX(i) : i, i1 = idx ? idx.getX(i + 1) : i + 1, i2 = idx ? idx.getX(i + 2) : i + 2;
      if (i1 >= pos.count || i2 >= pos.count) continue;
      a.fromBufferAttribute(pos, i0).applyMatrix4(m);
      b.fromBufferAttribute(pos, i1).applyMatrix4(m);
      c.fromBufferAttribute(pos, i2).applyMatrix4(m);
      out.push({ v: [a.clone(), b.clone(), c.clone()], col });
    }
  });
}

function render(tris: Tri[], w: number, h: number, camPos: THREE.Vector3, target: THREE.Vector3) {
  const rgb = new Uint8Array(w * h * 3);
  for (let i = 0; i < w * h; i++) { rgb[i * 3] = 250; rgb[i * 3 + 1] = 250; rgb[i * 3 + 2] = 250; }
  const cam = new THREE.PerspectiveCamera(40, w / h, 0.05, 500);
  cam.position.copy(camPos); cam.up.set(0, 1, 0); cam.lookAt(target);
  cam.updateMatrixWorld(true); cam.updateProjectionMatrix();
  const vp = new THREE.Matrix4().multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
  const key = new THREE.Vector3(12, 18, 14).normalize();
  const items = tris.map((t) => {
    const [A3, B3, C3] = t.v;
    const nrm = new THREE.Vector3().crossVectors(new THREE.Vector3().subVectors(B3, A3), new THREE.Vector3().subVectors(C3, A3));
    if (nrm.lengthSq() < 1e-14) return null;
    nrm.normalize();
    if (nrm.dot(camPos.clone().sub(A3)) < 0) nrm.negate();
