      A: { x: ((pr[0].x + 1) / 2) * w, y: ((1 - pr[0].y) / 2) * h, d: pr[0].z },
      B: { x: ((pr[1].x + 1) / 2) * w, y: ((1 - pr[1].y) / 2) * h, d: pr[1].z },
      C: { x: ((pr[2].x + 1) / 2) * w, y: ((1 - pr[2].y) / 2) * h, d: pr[2].z },
      col: t.col, sh,
