    const mny = Math.max(0, Math.floor(Math.min(A.y, B.y, C.y))), mxy = Math.min(h - 1, Math.ceil(Math.max(A.y, B.y, C.y)));
    if (mnx > mxx || mny > mxy) continue;
    const den = (B.x - A.x) * (C.y - A.y) - (B.y - A.y) * (C.x - A.x);
    if (Math.abs(den) < 1e-9) continue;
    const r = Math.min(255, it.col[0] * it.sh), g = Math.min(255, it.col[1] * it.sh), bl = Math.min(255, it.col[2] * it.sh);
    for (let y = mny; y <= mxy; y++) for (let x = mnx; x <= mxx; x++) {
