import { describe, it } from 'vitest';
import { writeFileSync } from 'node:fs';
import * as THREE from 'three';
import { calculateFlashDryer } from '../dryerCalculations';
import { extractParametricModel } from './parametricModel';
import { buildMechanicalCadAssembly } from './geometryBuilder';
import { createCadMaterials } from './materials';
import { DEFAULT_DRYER_INPUTS } from '../constants';

const f = (v: number) => +v.toFixed(4);

describe('probe: drawn inlet pieces at 40 t/h', () => {
  it('lists every piece with its world extent', () => {
    const model = extractParametricModel(calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS, feedRate: 40000 } as never));
    const { rootGroup } = buildMechanicalCadAssembly(model, createCadMaterials());
    const pipe: THREE.Mesh[] = [], cyc: THREE.Mesh[] = [];
    rootGroup.traverse((o) => {
      if (!(o as THREE.Mesh).isMesh) return;
      let n: THREE.Object3D | null = o;
      while (n) {
        if (n.name === 'component_column') { pipe.push(o as THREE.Mesh); break; }
        if (n.name === 'component_cyclone') { cyc.push(o as THREE.Mesh); break; }
        n = n.parent;
      }
    });

    const flangeX = model.cycloneInletFlangePoint.x;
    // the duct tube that ends at the flange
    let ductEnd: number | null = null;
    for (const m of pipe) {
      if (m.geometry.type !== 'TubeGeometry') continue;
      const b = new THREE.Box3().setFromObject(m, true);
      if (b.max.x > flangeX - 0.6 && b.max.x < flangeX + 0.6 && b.max.y > model.cycloneInletYM) {
        ductEnd = Math.max(ductEnd ?? -Infinity, b.max.x);
      }
    }

    const loft = pipe.find((m) => m.geometry.type === 'BufferGeometry');
    const loftBox = loft ? new THREE.Box3().setFromObject(loft, true) : null;

    const boxes = cyc
      .map((m) => ({ geo: m.geometry.type, b: new THREE.Box3().setFromObject(m, true) }))
      .filter((x) => x.b.max.x > model.cycloneInletFlangePoint.x - 1.0 && x.b.min.x < model.cycloneCenterXM)
      .map((x) => ({
        geo: x.geo,
        x: [f(x.b.min.x), f(x.b.max.x)],
        y: [f(x.b.min.y), f(x.b.max.y)],
        z: [f(x.b.min.z), f(x.b.max.z)],
        sy: f(x.b.max.y - x.b.min.y),
        sz: f(x.b.max.z - x.b.min.z),
      }));

    writeFileSync(`${process.env.TEMP}\\p40.json`, JSON.stringify({
      model: {
        flangeX: f(flangeX),
        transLen: f(model.cycloneInletTransitionLengthM),
        stubLen: f(model.cycloneInletStubLengthM),
        inletLen: f(model.cycloneInletLengthM),
        centreX: f(model.cycloneCenterXM),
        barrelR: f(model.cycloneBarrelRadiusM),
        shellX: f(model.cycloneCenterXM - model.cycloneBarrelRadiusM),
        inletH: f(model.cycloneInletHeightM),
        inletW: f(model.cycloneInletWidthM),
        builderWouldPlaceStubOuterAt: f(model.cycloneCenterXM - model.cycloneInletLengthM + model.cycloneInletTransitionLengthM),
      },
      ductEndX: ductEnd === null ? null : f(ductEnd),
      loftX: loftBox ? [f(loftBox.min.x), f(loftBox.max.x)] : null,
      loftY: loftBox ? [f(loftBox.min.y), f(loftBox.max.y)] : null,
      loftZ: loftBox ? [f(loftBox.min.z), f(loftBox.max.z)] : null,
      cycloneBoxes: boxes,
    }, null, 1));
  });
});

