import { calculateFlashDryer } from './dryerCalculations';
import { DEFAULT_DRYER_INPUTS } from './constants';

describe('probe: substitution strings', () => {
  it('dumps every step', () => {
    const r = calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS });
    const rows = r.calculationSteps.map((s) => ({
      key: `${s.category}|${s.symbol}`,
      hasEq: !!s.equationLatex,
      sub: s.substitution,
    }));
    writeFileSync(
      `${process.env.TEMP}\\subs.json`,
      JSON.stringify({ count: rows.length, rows }, null, 1)
    );
  });
});

