8:  * WHY NOT react-katex. The `react-katex` wrapper re-renders through its own
9:  * context and DOM-diffing layer, which is unnecessary here: every expression in
10:  * this app is a compile-time constant string, so a `useMemo` over the string
11:  * renders each one exactly once. Using KaTeX directly keeps one fewer dependency
12:  * and makes the failure path explicit ΓÇö `throw: false` means a malformed
13:  * expression degrades to a visible source string instead of blanking the panel.
14:  *
15:  * WHY A FALLBACK MATTERS. `renderToString` with `throw: false` silently returns
16:  * the source text plus an error colour when it cannot parse. On a page whose
17:  * entire purpose is auditing a calculation, an unparseable equation must be
18:  * visible, not swallowed. A developer running this app can see the bad LaTeX
19:  * immediately and fix it, which is what happened to the handful of expressions
20:  * that needed brace grouping during the original conversion.
21:  */
22: export const Latex: React.FC<{
23:   tex: string;
24:   className?: string;
25:   /** Render on one line, for inline use in a sentence. */
26:   inline?: boolean;
27: }> = ({ tex, className, inline = false }) => {
28:   const html = useMemo(() => {
29:     if (!tex || !tex.trim()) return '';
30:     try {
31:       return katex.renderToString(tex, {
32:         displayMode: !inline,
33:         throwOnError: false,
34:         strict: false,
35:         trust: false,
36:         output: 'html',
37:         macros: {
38:           '\\dd': '\\mathrm{d}',
39:           '\\degC': '{}^{\\circ}\\mathrm{C}',
40:           '\\kgm': '\\mathrm{kg\\,m^{-3}}',
41:         },
