/**
 * Converts the plain-text `substitution` string of a calculation step into LaTeX.
 *
 * WHY A CONVERTER AND NOT A LOOKUP TABLE.
 *
 * The equation table in `stepLatex.ts` is keyed by symbol and holds SYMBOLIC LaTeX
 * (`D_c = \sqrt{...}`), so a hand-written entry cannot go stale. The substitution is the
 * opposite: it holds LIVE COMPUTED NUMBERS ΓÇö `820.00 ├ù (1 - 0.400)` is whatever the
 * current inputs produce. A hand-written LaTeX substitution would hard-code today's
 * values and be wrong the instant anyone changes a feed rate, so it would have to be
 * regenerated on every edit. Converting the string that is actually about to be shown
 * means the typeset line and the plain line cannot disagree by construction.
 *
 * The grammar is narrow and regular, so this is a small recursive descent rather than a
 * general parser:
 *
 *     line       := statement ( (';' | '|') statement )*
 *     statement  := equality ( ('=' | '=>') equality )*
 *     equality   := fraction | term
 *     fraction   := term '/' term
 *     term       := function '(' ... ')' | 'sqrt[' ... ']' | atom*
 *     atom       := number | symbol | unit | operator | '( ... )' | '[ ... ]'
 *
 * Escaping happens only when a LEAF is produced, never on the assembled result, so the
 * braces this module inserts are not themselves escaped.
 */

/** Characters LaTeX treats specially and that appear in these strings. */
const SPECIALS: [RegExp, string][] = [
  [/%/g, '\\%'],
  [/&/g, '\\&'],
  [/#/g, '\\#'],
  [/\$/g, '\\$'],
  [/_/g, '\\_'],
];

/**
 * Units and words that must be set upright. Order matters: longer tokens first so
 * `kg/m^3` is not consumed by a shorter `m` rule.
 */
const UPRIGHT: string[] = [
  'kg/m┬│', 'lb/ft┬│', 'm┬│/rev', 'kg/h', 'kg/m┬▓', 'm/s', 'm┬│/h', 'Pa', 'kW', 'HP',
  'RPM', 'min', 'minutes', 'hour', 'hours', 'h', 'm', 'kg', 's', '┬░C',
];

/** Function calls that take a bracketed argument. */
const FUNCTIONS = ['sqrt', 'max', 'min', 'arctan', 'arcsin', 'arccos', 'sin', 'cos', 'tan', 'log', 'ln', 'exp'];

/** Sentinel for `=>` so the `=` split does not cut an arrow in half. */
const ARROW = '�ARROW�';

/**
 * Splits on `sep` at bracket depth zero. Returns null when `sep` does not occur at depth
 * zero, so the caller can treat the string as a single term.
 */
function splitTopLevel(s: string, sep: string): string[] | null {
  let depth = 0;
  const out: string[] = [];
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '(' || ch === '[' || ch === '{') depth++;
    else if (ch === ')' || ch === ']' || ch === '}') depth--;
    else if (depth === 0 && ch === sep) {
      // Skip a comparison or an arrow, not an equality.
      if (sep === '=' && (s[i + 1] === '=' || s[i + 1] === '>')) continue;
      out.push(s.slice(start, i));
      start = i + 1;
    }
  }
  if (!out.length) return null;
  out.push(s.slice(start));
  return out.map((p) => p.trim()).filter((p) => p.length > 0);
}

/** Sets units and bare words upright so they do not render as italic variables. */
function maskUpright(s: string): string {
  let out = s;
  for (const u of UPRIGHT) {
    // Only mask a whole word, never the tail of an identifier like `D_motor`.
    out = out.replace(
      new RegExp(`(^|[^A-Za-z0-9_.])(${u.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})(?![A-Za-z0-9_])`, 'g'),
      (_m, pre: string, tok: string) => `${pre}\\text{${tok}}`
    );
  }
  return out;
}

/** Wraps every run of bare Latin letters in `\mathrm{}`, for symbols like `pi`. */
function maskSymbols(s: string): string {
  return s
    .replace(/pi(?![A-Za-z0-9_])/g, '\\pi')
    .replace(/\b([A-Za-z]+(?:\s+[A-Za-z]+)*)\b/g, (m) =>
      /^\\/.test(m) || m.startsWith('\\text') || m.includes('\\') ? m : `\\mathrm{${m}}`
    );
}

/** Converts one leaf ΓÇö no top-level `=`, `/`, or bracketed function call remains. */
function leaf(s: string): string {
  let out = s;

  // Scientific notation: 2.278e-5 -> 2.278 \times 10^{-5}
  out = out.replace(/(\d+(?:\.\d+)?)[eE]([-+]?\d+)/g, (_m, num: string, ex: string) => {
    const e = Number(ex);
    return `${num} \\times 10^{${e < 0 ? '-' : ''}${Math.abs(e)}}`;
  });

  // Superscripts: ^2, ^-5, ^5.25588 -> ^{...}
  out = out.replace(/\^\{([^}]*)\}|\^(-?\d+(?:\.\d+)?|\d+)/g, (m, braced: string | undefined, bare: string | undefined) =>
    braced !== undefined ? `^{${braced}}` : `^{${bare}}`
  );

  // Units, then symbols, then the operators.
  out = maskUpright(out);
  out = maskSymbols(out);

  out = out
    .replace(/├ù/g, '\\times ')
    .replace(/┬╖/g, '\\cdot ')
    .replace(/├╖/g, '\\div ')
    .replace(/[ΓÇôΓÇö]/g, '-')
    .replace(/┬░/g, '^{\\circ}')
    .replace(/┬▓/g, '^{2}')
    .replace(/\bmod\b/g, '\\bmod ')
    .replace(/\bx\b/g, '\\times ');

  // Literal brackets around a whole group read better as \left[ \right].
  out = out.replace(/\[/g, '\\left[').replace(/\]/g, '\\right]');
  out = out.replace(/\(/g, '\\left(').replace(/\)/g, '\\right)');

  for (const [re, rep] of SPECIALS) out = out.replace(re, rep);

  return out;
}

/** Converts one expression, recursing through fractions, functions and brackets. */
function expression(s: string): string {
  const t = s.trim();
  if (!t) return '';

  const eq = splitTopLevel(t, '=');
  if (eq && eq.length > 1) {
    return eq
      .map((part) => (part === ARROW ? expression(eq[0]) : expression(part)))
      .join(' = ')
      .replace(new RegExp(`\\s=\\s*\\\\left?\\( ?${ARROW.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')} ?\\)`, 'g'), ' \\Rightarrow ')
      .split(`${ARROW} = `)
      .join(' \\Rightarrow ');
  }

  const fr = splitTopLevel(t, '/');
  if (fr && fr.length === 2) {
    return `\\dfrac{${expression(fr[0])}}{${expression(fr[1])}}`;
  }

  // A bracketed function call anywhere in the term: convert its argument and splice.
  for (const fn of FUNCTIONS) {
    const idx = t.indexOf(fn);
    if (idx === -1) continue;
    // The name must not be the tail of a longer identifier.
    if (idx > 0 && /[A-Za-z0-9_]/.test(t[idx - 1])) continue;
    const open = t[idx + fn.length];
    if (open !== '(' && open !== '[') continue;
    const close = open === '(' ? ')' : ']';
    const end = t.indexOf(close, idx + fn.length + 1);
    if (end === -1) continue;
    const arg = t.slice(idx + fn.length + 1, end);
    const head = t.slice(0, idx);
    const tail = t.slice(end + 1);
    const macro =
      fn === 'sqrt'
        ? `\\sqrt{${expression(arg)}}`
        : fn === 'arctan' || fn === 'arcsin' || fn === 'arccos'
          ? `\\${fn}\\left(${expression(arg)}\\right)`
          : `\\${fn}\\left(${expression(arg)}\\right)`;
    return `${expression(head)}${macro}${expression(tail)}`;
  }

  // A bare bracketed group: recurse so `x / [a * b]` becomes a real fraction.
  const bracket = t.match(/^[\[(](.*)[\])]$/);
  if (bracket) return `\\left${t[0]}${expression(bracket[1])}\\right${t[t.length - 1]}`;

  return leaf(t);
}

/** True when the line contains arithmetic worth typesetting. */
function hasArithmetic(s: string): boolean {
  return /[0-9]\s*(?:├ù|├╖|\/|\+|-|\^)|sqrt|arctan|\d\)/.test(s);
}

/**
 * The LaTeX form of a step's substitution, or null when the line is prose and reads
 * better untypeset (`Recommended Commercial Drive: 0.75 kW ...`), or contains no
 * arithmetic at all (`Loading = 30%`).
 *
 * Returning null rather than guessing lets the UI fall back to the plain string, so a
 * sentence is never mangled into italic nonsense.
 */
export function substitutionToLatex(plain: string): string | null {
  const trimmed = plain.trim();
  if (!trimmed || !hasArithmetic(trimmed)) return null;

  const guarded = trimmed
    .replace(/=>/g, ARROW)
    .replace(/>=/g, ' \\geq ')
    .replace(/<=/g, ' \\leq ');

  // Split the line into statements, then convert each and rejoin.
  const statements = guarded
    .split(/\s*[;|]\s*/)
    .map((p) => p.trim())
    .filter(Boolean);

  const parts = statements.map((st) => expression(st).replace(/\s+/g, ' ').trim()).filter(Boolean);
  if (!parts.length) return null;
  return parts.join(' \\quad ');
}

/** Exported for tests. */
export const _internal = { expression, leaf, splitTopLevel, hasArithmetic };

