import { describe, it, expect } from 'vitest';
import katex from 'katex';
import { substitutionToLatex, _internal } from './substitutionLatex';
import { calculateFlashDryer } from './dryerCalculations';
import { DEFAULT_DRYER_INPUTS } from './constants';

/**
 * Substitution LaTeX.
 *
 * The substitution holds LIVE COMPUTED NUMBERS, so these tests deliberately run the
 * engine across several input sets. A converter that only worked on the default inputs
 * would still be wrong for the user who actually changed something.
 */

const compiles = (tex: string) => {
  katex.renderToString(tex, { throwOnError: true, strict: false });
};

describe('substitutionToLatex: mechanics', () => {
  it('typesets a multiplication as a real operator, not an x', () => {
    expect(substitutionToLatex('820.00 ├ù (1 - 0.400)')).toContain('\\times');
    expect(substitutionToLatex('820.00 ├ù (1 - 0.400)')).not.toMatch(/[^\\]x[^a-zA-Z]/);
  });

  it('builds a real fraction from a slash', () => {
    const tex = substitutionToLatex('492.00 / (1 - 0.120)')!;
    expect(tex).toContain('\\frac');
    expect(tex).not.toMatch(/[^\\]\//);
  });

  it('converts a nested fraction inside brackets', () => {
    // The slash here is inside [], not at the top level, so it must be found by
    // recursing into the group rather than splitting the whole line.
    const tex = substitutionToLatex('1.1 ├ù [ (820.0 ├ù 10) / (380 ├ù 60) ]')!;
    expect(tex).toContain('\\frac');
    expect(tex).toContain('380 \\left( 60 \\right)');
  });

  it('turns sqrt[...] into a real radical', () => {
    const tex = substitutionToLatex('sqrt[ (4 ├ù 2.252) / (pi ├ù 14.0) ]')!;
    expect(tex).toContain('\\sqrt{');
    expect(tex).toContain('\\pi');
  });

  it('expands scientific notation to a power of ten', () => {
    const tex = substitutionToLatex('9.650 ├ù 2.278e-5 / (0.874 ├ù 2.300e-4)')!;
    expect(tex).toContain('10^{-5}');
    expect(tex).toContain('10^{-4}');
    expect(tex).not.toMatch(/e-?\d/);
  });

  it('braces a bare exponent', () => {
    expect(substitutionToLatex('6.4 ├ù 0.5 ├ù 0.986 ├ù (15.0)^2')).toContain('^{2}');
  });

  it('escapes the percent sign instead of eating the rest of the line', () => {
    // An unescaped % in LaTeX comments out everything after it. That is a silent,
    // total loss of the expression, so it must never reach the renderer.
    const tex = substitutionToLatex('1.5 ├ù 200 / 30%')!;
    expect(tex).toContain('\\%');
    expect(() => compiles(tex)).not.toThrow();
  });

  it('escapes an underscore so a symbol name is not read as a subscript', () => {
    const tex = substitutionToLatex('Q_v,imp ├ù 35.3147')!;
    expect(tex).toContain('\\_');
  });

  it('strips thousands separators so a digit run is not a decimal comma', () => {
    const tex = substitutionToLatex('(3.28 ├ù 55 ├ù 12 ├ù 1.0) / 1,000,000')!;
    expect(tex).toContain('1000000');
    expect(tex).not.toMatch(/1,000,000/);
  });

  it('sets units upright rather than italic', () => {
    const tex = substitutionToLatex('2501 - 2.361 ├ù 70.0')!;
    expect(tex).toContain('\\text{');
  });

  it('keeps a degree sign readable', () => {
    expect(substitutionToLatex('2.454 / 0.140 ├ù 100')).toBeTruthy();
    expect(substitutionToLatex('820.0 ├ù 10 / 60')).toBeTruthy();
    const deg = substitutionToLatex('2.454 / 0.140 - 0.05');
    expect(deg).toBeTruthy();
  });

  it('returns null for prose so the plain line is shown instead', () => {
    // A sentence typeset in math mode renders as italic nonsense. Returning null lets the
    // UI fall back to the plain string, which is the honest outcome.
    expect(substitutionToLatex('Recommended Commercial Drive: 0.75 kW Geared Motor')).toBeNull();
    expect(substitutionToLatex('F_o = 3.0')).toBeNull();
    expect(substitutionToLatex('')).toBeNull();
    expect(substitutionToLatex('   ')).toBeNull();
  });

  it('does not split on a comparison operator', () => {
    const eqs = _internal.splitTopLevel('55 >= 55', '=');
    expect(eqs, '>= must not be read as an equality').toBeNull();
  });
});

describe('substitutionToLatex: every step, every input set', () => {
  const CASES: [string, Parameters<typeof calculateFlashDryer>[0]][] = [
    ['default', { ...DEFAULT_DRYER_INPUTS }],
    ['1 t/h', { ...DEFAULT_DRYER_INPUTS, feedRate: 1000 }],
    ['40 t/h', { ...DEFAULT_DRYER_INPUTS, feedRate: 40000 }],
    ['D=1000', { ...DEFAULT_DRYER_INPUTS, standardPipeNominalMm: 1000 }],
    ['dry product 12%', { ...DEFAULT_DRYER_INPUTS, finalMoisture: 8 }],
  ];

  for (const [label, inputs] of CASES) {
    it(`every substitution LaTeX compiles ΓÇö ${label}`, () => {
      const steps = calculateFlashDryer(inputs).steps;
      const failures: string[] = [];
      for (const s of steps) {
        if (!s.substitutionLatex) continue;
        try {
          compiles(s.substitutionLatex);
        } catch (e) {
          failures.push(`${s.category}|${s.symbol}: ${(e as Error).message}`);
        }
      }
      expect(failures, `unparseable substitution LaTeX:\n${failures.join('\n')}`).toEqual([]);
    });
  }

  it('covers the large majority of the 60 default steps', () => {
    const steps = calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }).steps;
    const typed = steps.filter((s) => !!s.substitutionLatex).length;
    // Every line with real arithmetic should be typeset. The remainder are prose or
    // bare assignments, which are deliberately left as text.
    expect(typed, `only ${typed}/${steps.length} substitutions were typeset`).toBeGreaterThanOrEqual(
      steps.length * 0.6
    );
  });

  it('leaves the plain substitution untouched, so it can still be copied', () => {
    const steps = calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }).steps;
    for (const s of steps) {
      expect(s.substitution, 'the plain form must survive for copy/paste').toBeTruthy();
      if (s.substitutionLatex) {
        // The numbers in the plain string must all appear in the typeset one, otherwise
        // the converter dropped or mangled a value.
        const plainNumbers = s.substitution.match(/\d+(?:\.\d+)?/g) ?? [];
        for (const n of plainNumbers.slice(0, 6)) {
          expect(
            s.substitutionLatex,
            `${s.category}|${s.symbol}: value ${n} vanished from the LaTeX`
          ).toContain(n);
        }
      }
    }
  });

  it('every equation step still has its equation LaTeX', () => {
    const steps = calculateFlashDryer({ ...DEFAULT_DRYER_INPUTS }).steps;
    expect(steps.every((s) => !!s.equationLatex)).toBe(true);
  });
});

/**
 * Converts the plain-text `substitution` string of a calculation step into LaTeX.
 *
 * WHY A CONVERTER AND NOT A LOOKUP TABLE
 *
 * The equation table in `stepLatex.ts` is keyed by symbol and holds SYMBOLIC LaTeX
 * (`D_c = \sqrt{...}`), so a hand-written entry cannot go stale. The substitution is the
 * opposite: it holds LIVE COMPUTED NUMBERS ΓÇö `820.00 ├ù (1 - 0.400)` is whatever the
 * current inputs produce. A hand-written LaTeX substitution would hard-code today's
 * values and be wrong the instant anyone changes a feed rate, so it would have to be
 * regenerated on every edit. Converting the string that is actually about to be shown
 * means the typeset line and the plain line cannot disagree by construction.
 *
 * GRAMMAR ΓÇö a small recursive descent, not a general parser:
 *
 *     line       := statement ( (';' | '|') statement )*
 *     statement  := equality ( ('=' | '=>') equality )*
 *     equality   := fraction | term
 *     fraction   := term '/' term
 *     term       := function '(' ... ')' | 'sqrt[' ... ']' | group | atom*
 *
 * ORDERING IS THE WHOLE PROBLEM, so it is worth stating. Three things must happen in this
 * sequence, and reversing any pair breaks output:
 *
 *   1. Escape LaTeX specials FIRST. After this point nothing may be escaped again,
 *      because every later step inserts braces of its own.
 *   2. Claim units, by swapping them for placeholders. Otherwise the word wrapper steals
 *      `kg` out of `kg/h` and leaves a stray slash.
 *   3. Wrap bare words, numbers and operators last, around whatever survives.
 *
 * Bracketed groups are lifted out into placeholders before any of this, so that a group
 * can be converted on its own ΓÇö that is how a slash buried inside `[...]` is found.
 */

/** LaTeX specials that occur in these strings. Escaped before anything is inserted. */
const SPECIALS: [RegExp, string][] = [
  [/%/g, '\\%'],
  [/&/g, '\\&'],
  [/#/g, '\\#'],
  [/\$/g, '\\$'],
  [/_/g, '\\_'],
];

/**
 * Units, longest first so `kg/m^3` is claimed before `m`.
 *
 * Superscript-3 is written `m┬│` in the source strings, not `m^3`.
 */
const UNITS = [
  'kg/m┬│', 'lb/ft┬│', 'm┬│/rev', 'kg/h', 'kg/m┬▓', 'kg/s', 'm/s', 'm┬│/h', 'm┬▓/s',
  'HP', 'RPM', 'Pa', 'kW', 'min', 'm┬│', 'm┬▓', 'kg', 'cm', 'mm', '┬░C',
  'minutes', 'hours', 'minute', 'hour', 'Pa┬╖s',
];

/** Macro names that must never be mistaken for a bare word. */
const MACROS = new Set([
  'text', 'mathrm', 'frac', 'dfrac', 'sqrt', 'left', 'right', 'cdot', 'times',
  'div', 'pi', 'geq', 'leq', 'Rightarrow', 'mathrm', 'bmod', 'left', 'right',
]);

/** Function calls that take a bracketed argument. */
const FUNCTIONS = new Set([
  'sqrt', 'max', 'min', 'arctan', 'arcsin', 'arccos', 'sin', 'cos', 'tan', 'log', 'ln', 'exp',
]);

/**
 * Scratch storage for the two kinds of placeholder this module lifts out of a string:
 * `\u0001` for a converted bracket group, `\u0002` for a claimed unit.
 *
 * Module scope because a placeholder can be created deep in the recursion and only be
 * resolved once the whole line is built. Safe here: `substitutionToLatex` resets both
 * arrays on entry, is synchronous, and the app never calls it re-entrantly.
 */
let groups: string[] = [];
let units: string[] = [];

const GROUP_PH = (i: number) => `${i}`;
const UNIT_PH = (i: number) => `${i}`;

/** Splits on `sep` at bracket depth zero. Returns null when `sep` is absent there. */
function splitTopLevel(s: string, sep: string): string[] | null {
  let depth = 0;
  const out: string[] = [];
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '(' || ch === '[') depth++;
    else if (ch === ')' || ch === ']') depth--;
    else if (depth === 0 && ch === sep) {
      // `>=`, `<=` and `=>` are not equalities. Guard the character on BOTH sides: a
      // forward-only guard reads `55 >= 55` as `55 >` split from `55`.
      const prev = s[i - 1];
      const next = s[i + 1];
      if (prev === '>' || prev === '<' || next === '=' || next === '>') continue;
      out.push(s.slice(start, i));
      start = i + 1;
    }
  }
  if (!out.length) return null;
  out.push(s.slice(start));
  const parts = out.map((p) => p.trim()).filter(Boolean);
  return parts.length ? parts : null;
}

/** Claims every unit token, replacing it with a placeholder. */
function claimUnits(s: string): string {
  let out = s;
  for (const u of UNITS) {
    const esc = u.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    out = out.replace(
      new RegExp(`(^|[^A-Za-z0-9_.\\])(?:(${esc}))(?![A-Za-z0-9_])`, 'g'),
      (_m, pre: string, tok: string) => `${pre}${UNIT_PH(units.push(tok) - 1)}`
    );
  }
  return out;
}

/**
 * Lifts every innermost bracket group out into a placeholder, converting its contents.
 *
 * Must run AFTER function names are handled, or `sqrt[...]` loses its name.
 */
function liftGroups(s: string): string {
  for (;;) {
    let open = -1;
    let close = -1;
    for (let i = 0; i < s.length; i++) {
      if (s[i] !== '(' && s[i] !== '[') continue;
      let depth = 0;
      let j = i;
      let end = -1;
      for (; j < s.length; j++) {
        if (s[j] === '(' || s[j] === '[') depth++;
        else if (s[j] === ')' || s[j] === ']') {
          depth--;
          if (depth === 0) { end = j; break; }
        }
      }
      if (end === -1) continue;
      const inner = s.slice(i + 1, end);
      if (/[()[\]]/.test(inner)) continue; // not innermost
      open = i;
      close = end;
      break;
    }
    if (open === -1) return s;
    const opener = s[open];
    const closer = s[close] === ')' ? ')' : ']';
    const converted = `\\left${opener}${expression(s.slice(open + 1, close))}\\right${closer}`;
    groups.push(converted);
    s = s.slice(0, open) + GROUP_PH(groups.length - 1) + s.slice(close + 1);
  }
}

/** Converts one leaf: no `=`, `/`, function call or bracket group remains. */
function leaf(s: string): string {
  let out = s;

  // Strip thousands separators, or `1,000,000` renders with a decimal point.
  out = out.replace(/(\d),(\d{3})(?!\d)/g, '$1$2');

  // Scientific notation: 2.278e-5 -> 2.278 \times 10^{-5}
  out = out.replace(
    /(\d+(?:\.\d+)?)[eE]([-+]?\d+)/g,
    (_m, num: string, ex: string) => {
      const e = Number(ex);
      return `${num} \\times 10^{${e < 0 ? '-' : ''}${Math.abs(e)}}`;
    }
  );

  // Bare superscripts: ^2, ^-5, ^5.25588 -> ^{...}
  out = out.replace(
    /\^\{([^}]*)\}|\^(-?\d+(?:\.\d+)?)/g,
    (_m, braced: string | undefined, bare: string | undefined) =>
      braced !== undefined ? `^{${braced}}` : `^{${bare}}`
  );

  // pi, before the word wrapper so it is not treated as a word.
  out = out.replace(/(^|[^A-Za-z0-9_\\])pi(?![A-Za-z0-9_])/g, '$1\\pi');

  out = claimUnits(out);

  // Wrap every remaining bare word run upright, so an English phrase reads as text
  // rather than as a string of italic variables.
  out = out.replace(
    /[A-Za-z][A-Za-z0-9_\\]*(?:[ ][A-Za-z][A-Za-z0-9_\\]*)*/g,
    (word: string, at: number, whole: string) => {
      const before = at > 0 ? whole[at - 1] : '';
      // Skip a macro name, and anything already sitting in a placeholder.
      if (before === '\\' || before === '' || before === '') return word;
      if (MACROS.has(word)) return word;
      return `\\text{${word}}`;
    }
  );

  out = out
    .replace(/├ù/g, '\\times ')
    .replace(/┬╖/g, '\\cdot ')
    .replace(/├╖/g, '\\div ')
    .replace(/[ΓÇôΓÇö]/g, '-')
    .replace(/┬░/g, '^{\\circ}')
    .replace(/┬▓/g, '^{2}')
    .replace(/\bmod\b/g, '\\bmod ')
    .replace(/ (?=\d)/g, '\\; ');

  return out;
}

/** Converts one expression, recursing through equalities, functions, fractions, groups. */
function expression(s: string): string {
  const t = s.trim();
  if (!t) return '';

  const eq = splitTopLevel(t, '=');
  if (eq && eq.length > 1) return eq.map(expression).join(' = ');

  const fr = splitTopLevel(t, '/');
  if (fr && fr.length === 2) {
    return `\\dfrac{${expression(fr[0])}}{${expression(fr[1])}}`;
  }

  // A function call, handled before group lifting so the name survives.
  for (const fn of FUNCTIONS) {
    let from = 0;
    for (;;) {
      const at = t.indexOf(fn, from);
      if (at === -1) break;
      from = at + fn.length;
      if (at > 0 && /[A-Za-z0-9_\\]/.test(t[at - 1])) continue;
      const open = t[at + fn.length];
      if (open !== '(' && open !== '[') continue;
      let depth = 0;
      let end = -1;
      for (let j = at + fn.length; j < t.length; j++) {
        if (t[j] === '(' || t[j] === '[') depth++;
        else if (t[j] === ')' || t[j] === ']') {
          depth--;
          if (depth === 0) { end = j; break; }
        }
      }
      if (end === -1) continue;
      const arg = expression(t.slice(at + fn.length + 1, end));
      const tail = liftGroupsAndLeaf(t.slice(end + 1));
      return fn === 'sqrt'
        ? `${expression(t.slice(0, at))}\\sqrt{${arg}}${tail}`
        : `${expression(t.slice(0, at))}\\${fn}\\left(${arg}\\right)${tail}`;
    }
  }

  return liftGroupsAndLeaf(t);
}

/** Lifts bracket groups out of a string, then converts what is left as a leaf. */
function liftGroupsAndLeaf(s: string): string {
  return leaf(liftGroups(s));
}

/**
 * The LaTeX form of a step's substitution, or null for an empty line.
 *
 * Everything is typeset, including prose: words are wrapped upright, so a sentence such
 * as `Recommended Commercial Drive: 0.75 kW ...` renders as readable text with its
 * numbers set properly, rather than as a row of italic variables.
 */
export function substitutionToLatex(plain: string): string | null {
  const trimmed = plain.trim();
  if (!trimmed) return null;

  groups = [];
  units = [];

  const guarded = trimmed
    .replace(/=>/g, '\\ \\Rightarrow\\ ')
    .replace(/>=/g, ' \\geq ')
    .replace(/<=/g, ' \\leq ');

  const statements = guarded
    .split(/\s*[;|]\s*/)
    .map((p) => p.trim())
    .filter(Boolean);

  const parts = statements
    .map((st) => expression(st).replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  if (!parts.length) return null;

