// ITEM 33 ΓÇö the clean-air exhaust stack, sized from the FAN and moved clear of the
    // suction duct.
    //
    // Two defects, both reported from the same screenshot.
    //
    // (a) WRONG REFERENCE. The stack radius was
    //     `max(0.12, cycloneVortexFinderRadiusM * 0.95)` ΓÇö taken from the CYCLONE's
    //     vortex finder, an upstream component with no dimensional relationship to the
    //     fan discharge. On the IITA load that is 0.289 m (a 580 mm stack) hanging off
    //     a nozzle that is only 428 x 428 mm, so the vent was oversized against the
    //     very thing it bolts to and no transition existed between them.
    //     It is now sized from the nozzle AREA, so it passes the same mass flow at the
    //     same velocity, and the stack diameter tracks the fan instead of the cyclone.
    //
    // (b) COLLISION. The stack stood at `dbR * 0.75` in +X of the volute, which is the
    //     same side the overhead suction duct descends. On the IITA load the two
    //     interpenetrated by 0.227 m in X over 2.05 m of Y ΓÇö the vent passing straight
    //     through the duct. It is now placed on the far side of the volute (-X), and the
    //     clearance is asserted in the test suite rather than left to the eye.

    const stackHeight = 2.4;
    const nozW = params.downstreamBlowerOutletWidthM;
    const nozH = params.downstreamBlowerOutletHeightM;
    // Equal-area round stack: same discharge area as the rectangular nozzle.
    const stackR = params.downstreamStackRadiusM;

    // Discharge nozzle sits on +X of the volute, so the stack goes to -X. That is the
    // side the suction duct (which descends at +X) never occupies.
    //
    // The standoff clears the descending duct's RADIUS, not just the volute. The duct
    // is sized from the cyclone's vortex finder, which is independent of the drying
    // pipe, so on a small-pipe / large-cyclone design it is wider than the volute and
    // reached across to -X. Offsetting only past the volute left 21 mm of clearance at
    // D=100 mm ΓÇö non-intersecting, but far too thin to be a real arrangement.
    const ductClearR = params.cycloneVortexFinderRadiusM;
    const stackBaseX = -(dbR * 0.5 + dbW * 0.5 + ductClearR + stackR + 0.15);
    const stackBaseY = dbR * 0.55;

    // Square-to-round transition from the rectangular nozzle down to the round stack.
    // This is the connector between two dissimilar shapes; it is a real converging
    // piece, sized on the nozzle face and the stack diameter, not a coincident pair of
    // cylinders that merely happen to overlap.
    const dTransGeo = new THREE.CylinderGeometry(stackR, Math.min(nozW, nozH) * 0.5, dbR * 0.9, 24);
    dTransGeo.rotateZ(Math.PI / 2);
    const dTransMesh = new THREE.Mesh(dTransGeo, materials.stainlessSteel);
    dTransMesh.position.set(stackBaseX + dbR * 0.45, stackBaseY, 0);
    dTransMesh.castShadow = true;
    downstreamBlowerGroup.add(dTransMesh);

    const dStackGeo = new THREE.CylinderGeometry(stackR, stackR, stackHeight, 24);
    const dStackMesh = new THREE.Mesh(dStackGeo, materials.stainlessSteel);
    dStackMesh.position.set(stackBaseX, stackBaseY + stackHeight / 2, 0);
    dStackMesh.castShadow = true;
    downstreamBlowerGroup.add(dStackMesh);

    // Flanged connection where the transition meets the stack.
    const dDischFlange = createFlangeJoint(stackR, 0.016, materials, 8);
    dDischFlange.position.set(stackBaseX, stackBaseY + 0.05, 0);
    downstreamBlowerGroup.add(dDischFlange);

    // Weather cowl / diffuser hood at stack discharge
    const dCowlGeo = new THREE.ConeGeometry(stackR * 1.5, 0.28, 20);
    const dCowlMesh = new THREE.Mesh(dCowlGeo, materials.stainlessSteelDark);
    dCowlMesh.position.set(stackBaseX, stackBaseY + stackHeight + 0.14, 0);
    downstreamBlowerGroup.add(dCowlMesh);

