// ITEM 38 ΓÇö the reducer between the outlet duct and the fan suction throat.
  //
  // The duct is 0.579 m at the IITA load; the throat is 0.433 m. The duct overhung the
  // opening by 146 mm in diameter and could not enter it. Both ends are round and
  // coaxial, so the correct transition is a concentric cone ΓÇö and unlike the inlet-side
  // case there is nothing to loft, because there is no rectangle to match.
  //
  // Its radius is taken from the two ACTUAL sections rather than from a fraction of one
  // of them. The old adapter idiom, `max(a, b) * 0.62`, is what made the inlet-side
  // version 243 mm oversized on each side in Z; the rule here is simply "match each end
  // to what it joins".
  {
    const nozzleR = params.downstreamBlowerInletRadiusM;
    const rIn = ductR;                 // duct side, upstream
    const rOut = nozzleR;              // throat side, downstream
    const geo = new THREE.CylinderGeometry(rOut, rIn, reducerLen, 32, 1, true);
    geo.rotateX(Math.PI / 2);          // axis along +Z, matching the duct's approach
    const mesh = new THREE.Mesh(geo, materials.stainlessSteel);
    mesh.position.set(idSuctionPt.x, idSuctionPt.y, idSuctionPt.z - reducerLen / 2);
    mesh.castShadow = true;
    overheadDuctGroup.add(mesh);
  }

