describe('item 35: the cyclone-to-fan arch is two real quarter bends', () => {
  /**
   * The arch is: up the vortex finder, quarter bend to horizontal, straight across,
   * quarter bend down to the drop. Each bend must be tangent-continuous, and the two
   * must share the crown elevation so the straight joins them.
   */
  const arch = (m: ParametricModel3D) => {
    const cyX = m.downstreamBlowerPosition.x - Math.max(1.8, m.cycloneBarrelRadiusM + 1.2);
    const dbX = m.downstreamBlowerPosition.x;
    const cyTopY = m.cycloneBarrelTopYM + 0.4;
    const crownSpan = Math.abs(dbX - cyX);
    const crownRise = 0.65;
    const R = Math.max(1e-3, Math.min(m.bendRadiusM, crownSpan / 2, crownRise));
    const apexY = cyTopY + R;
    const b1Start: [number, number] = [cyX, cyTopY];
    const b1End: [number, number] = [cyX + R, apexY];
    const b2Start: [number, number] = [dbX - R, apexY];
    const b2End: [number, number] = [dbX, cyTopY];
    return { R, apexY, b1Start, b1End, b2Start, b2End, crownSpan };
  };

  it('both bends share one radius and one crown elevation', () => {
    // Two different radii cannot share a crown: bend 1 must end where bend 2 begins.
    // An earlier version clamped the span and the rise separately, which made the two
    // arcs cross over each other at the apex.
    const a = arch(model());
    expect(a.b1End[1]).toBeCloseTo(a.apexY, 9);
    expect(a.b2Start[1]).toBeCloseTo(a.apexY, 9);
  });

  it('bend 1 leaves the vortex finder axis and arrives on the crown', () => {
    const a = arch(model());
    expect(a.b1Start[0]).toBeGreaterThan(0); // anchored to the riser side
    expect(a.b1End[0]).toBeCloseTo(a.b1Start[0] + a.R, 9);
  });

  it('bend 2 departs the crown and arrives on the fan drop axis', () => {
    const a = arch(model());
    expect(a.b2End[0]).toBeCloseTo(a.b2Start[0] + a.R, 9);
    expect(a.b2End[1]).toBeCloseTo(a.b1Start[1], 9);
  });

  it('the two bends do not overlap, so a straight always remains between them', () => {
    for (const dia of [100, 180, 315, 450, 630, 1000]) {
      const a = arch(model({ standardPipeNominalMm: dia }));
      expect(a.b2Start[0] - a.b1End[0], `D=${dia}: bends overlap`).toBeGreaterThanOrEqual(0);
    }
  });

  it('the radius never exceeds what the geometry can supply', () => {
    for (const dia of [100, 180, 315, 450, 630, 1000]) {
      const m = model({ standardPipeNominalMm: dia });
      const a = arch(m);
      expect(a.R, `D=${dia}: radius exceeds the span`).toBeLessThanOrEqual(a.crownSpan / 2 + 1e-9);
      expect(a.R, `D=${dia}: radius exceeds the rise`).toBeLessThanOrEqual(0.65 + 1e-9);
      expect(a.R, `D=${dia}: radius exceeds the engine bend radius`).toBeLessThanOrEqual(m.bendRadiusM + 1e-9);
    }
  });
});

