input.script:
(async () => {
  const c=document.querySelector('canvas');
  const stat=(cv)=>{
    const t=document.createElement('canvas'); t.width=60; t.height=60;
    const x=t.getContext('2d'); x.drawImage(cv,0,0,60,60);
    const d=x.getImageData(0,0,60,60).data;
    let nonwhite=0; for(let i=0;i<d.length;i+=4){ if(d[i]<240||d[i+1]<240||d[i+2]<240) nonwhite++; }
    return nonwhite;
  };
  const small=(q)=>{ const g=document.createElement('canvas'); g.width=300; g.height=Math.round(300*c.height/c.width);
    const x=g.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,g.width,g.height); x.drawImage(c,0,0,g.width,g.height);
    return g.toDataURL('image/jpeg',q).split(',')[1]; };

  const out={ before: stat(c) };

  // 1) read inside a requestAnimationFrame callback
  await new Promise(res=>requestAnimationFrame(()=>{
    out.inRaf = stat(c); out.rafLen = small(0.4).length; res();
  }));

  // 2) force a renderer resize+render, then read synchronously
  window.dispatchEvent(new Event('resize'));
  out.afterResize = stat(c);
  out.resizeLen = small(0.4).length;
  out.resizeB64 = small(0.4);

  return out;
})()

